INSERT INTO grammar_lesson (id, subject_id, grade, semester, category, title, summary, content_md, examples, common_mistakes, mnemonic, order_index, source, deleted, created_at, updated_at) VALUES (1, 2, 3, NULL, '词法·名词', '名词的分类（可数与不可数）', '名词分两种：能数清的是可数，数不清的是不可数。', '## 这是啥
小朋友们，名词就是表示“东西”的词，比如 apple（苹果）、water（水）。

名词分两类：
- **可数名词**：能一个一个数出来。比如 one apple, two apples。
- **不可数名词**：不好一个一个数。比如 water（水），我们不说 two waters。

## 怎么用

### 1. 可数名词：能数，有单数和复数
可数名词前面可以加 a / an，也可以加数字。
- 一个：a book（一本书）
- 很多：two books（两本书）

例句：I have a cat. 我有一只猫。

### 2. 可数名词复数：一般加 -s
大多数可数名词，变复数时在词尾加 -s。
- one dog → two dogs（一只狗 → 两只狗）

例句：She has three pens. 她有三支笔。

### 3. 不可数名词：不能加 a / an，也不能加 -s
不可数名词前面不能加 a / an，也不能变复数。
- 对：I drink water. 我喝水。
- 错：I drink a water. / I drink waters.

例句：I like milk. 我喜欢牛奶。

### 4. 不可数名词想表示“多少”，用 much 或 some
不可数名词可以用 some（一些）或 much（很多）来帮忙。
- some water（一些水）
- much rice（很多米饭）

例句：There is some juice in the cup. 杯子里有一些果汁。', '[{"en": "I have a cat.", "zh": "我有一只猫。"}, {"en": "She has three pens.", "zh": "她有三支笔。"}, {"en": "I drink water.", "zh": "我喝水。"}, {"en": "I like milk.", "zh": "我喜欢牛奶。"}, {"en": "There is some juice in the cup.", "zh": "杯子里有一些果汁。"}, {"en": "He eats two apples.", "zh": "他吃两个苹果。"}, {"en": "We need some rice.", "zh": "我们需要一些米饭。"}]', '["I drink a water. 不能说 a water，water 是不可数名词。", "I have two book. 两只书要加 -s，说 two books。", "She likes milks. milk 不可数，不能加 -s。", "I eat a rice. rice 不可数，不能说 a rice。", "There are some waters. water 不可数，不能说 waters。"]', '可数名词能数清，一个两个加 -s；不可数名词数不清，some 和 much 来帮忙。', 0, 'ai', 0, '2026-09-18 17:34:16.226419', '2026-09-27 21:42:23.846660') ON CONFLICT(id) DO UPDATE SET subject_id=excluded.subject_id, grade=excluded.grade, semester=excluded.semester, category=excluded.category, title=excluded.title, summary=excluded.summary, content_md=excluded.content_md, examples=excluded.examples, common_mistakes=excluded.common_mistakes, mnemonic=excluded.mnemonic, order_index=excluded.order_index, source=excluded.source, deleted=excluded.deleted, created_at=excluded.created_at, updated_at=excluded.updated_at;
INSERT INTO grammar_lesson (id, subject_id, grade, semester, category, title, summary, content_md, examples, common_mistakes, mnemonic, order_index, source, deleted, created_at, updated_at) VALUES (2, 2, 3, NULL, '词法·名词', '名词复数规则（s/es/特殊变化）', '名词复数不难记，一般加s，s/x/ch/sh加es，特殊变化要牢记！', '## 这是啥

小朋友，你有没有发现？

- 一个苹果：**an apple**
- 两个苹果：**two apples**

英语里，**一个**东西用“单数”，**两个或更多**就用“复数”。

复数怎么变？大多数时候，在单词后面加个小尾巴 **s** 就行啦！

## 怎么用

### 1. 大多数名词，直接加 s

比如：

- book → book**s**
- pen → pen**s**
- cat → cat**s**

例句：I have two **books**. 我有两本书。

### 2. 结尾是 s, x, ch, sh，要加 es

这些词尾巴“嘶嘶”响，加 s 听不清，所以要加 **es**。

- bus → bus**es**
- box → box**es**
- watch → watch**es**
- dish → dish**es**

例句：There are three **buses**. 有三辆公交车。

### 3. 特殊变化，要单独记

有些词很调皮，不按规则变：

- man → **men**
- woman → **women**
- child → **children**
- foot → **feet**
- tooth → **teeth**

例句：I see two **children**. 我看见两个孩子。

### 4. 有些词单复数长得一样

比如 sheep（羊）、fish（鱼）。

- one sheep → two **sheep**
- one fish → two **fish**

例句：I have three **sheep**. 我有三只羊。', '[{"en": "I have two apples.", "zh": "我有两个苹果。"}, {"en": "She has three books.", "zh": "她有三本书。"}, {"en": "There are four buses.", "zh": "有四辆公交车。"}, {"en": "I see two boxes.", "zh": "我看见两个盒子。"}, {"en": "The children are playing.", "zh": "孩子们正在玩耍。"}, {"en": "My feet are big.", "zh": "我的脚很大。"}, {"en": "I have three sheep.", "zh": "我有三只羊。"}, {"en": "We have five watches.", "zh": "我们有五块手表。"}]', '["two book（忘记加s，应该是 two books）", "three boxs（应该加es，写成 three boxes）", "two mans（特殊变化，应该是 two men）", "five childs（特殊变化，应该是 five children）", "three sheeps（sheep单复数一样，不加s）"]', '一般加s，s/x/ch/sh加es，特殊变化单独记，单复同形别忘记！', 1, 'ai', 0, '2026-09-18 17:34:16.226419', '2026-09-21 14:52:27.285860') ON CONFLICT(id) DO UPDATE SET subject_id=excluded.subject_id, grade=excluded.grade, semester=excluded.semester, category=excluded.category, title=excluded.title, summary=excluded.summary, content_md=excluded.content_md, examples=excluded.examples, common_mistakes=excluded.common_mistakes, mnemonic=excluded.mnemonic, order_index=excluded.order_index, source=excluded.source, deleted=excluded.deleted, created_at=excluded.created_at, updated_at=excluded.updated_at;
INSERT INTO grammar_lesson (id, subject_id, grade, semester, category, title, summary, content_md, examples, common_mistakes, mnemonic, order_index, source, deleted, created_at, updated_at) VALUES (3, 2, 4, NULL, '词法·名词', '名词所有格（''s 与 of）', '东西有主人，''s 站身后；无生命用 of，位置要记熟。', '## 这是啥
小朋友，你有没有说过「这是**小明的**书包」？
英语里说「谁的」，就要用到**名词所有格**。
简单说：**所有格就是表示「谁的」**。

## 怎么用
### 要点1：有生命的东西，后面加 ''s
人、动物这些「活的东西」，后面加 **''s**。
- 例子：This is **Tom''s** book. （这是汤姆的书。）

### 要点2：名字结尾是 s，只加 ''
如果名字本身以 s 结尾，后面只加一个 **''**，不用再加 s。
- 例子：This is **James''** bag. （这是詹姆斯的包。）

### 要点3：没有生命的东西，用 of
桌子、房子、书这些「不会动的东西」，用 **of** 来表示「的」。
- 例子：The door **of** the room is open. （房间的门是开着的。）

### 要点4：两个人都有的东西，各加 ''s
如果是两个人**各自**的东西，两个名字后面都要加 ''s。
- 例子：**Tom''s and Sam''s** bags are new. （汤姆的包和山姆的包都是新的。）

## 小提醒
- ''s 和 of 都表示「的」，但用法不一样。
- 有生命 → ''s；无生命 → of。
- 记住：**人用 ''s，物用 of**。', '[{"en": "This is Tom''s book.", "zh": "这是汤姆的书。"}, {"en": "This is James'' bag.", "zh": "这是詹姆斯的包。"}, {"en": "The door of the room is open.", "zh": "房间的门是开着的。"}, {"en": "Tom''s and Sam''s bags are new.", "zh": "汤姆的包和山姆的包都是新的。"}, {"en": "The cat''s tail is long.", "zh": "猫的尾巴很长。"}, {"en": "The color of the car is red.", "zh": "汽车的颜色是红色的。"}, {"en": "My sister''s doll is cute.", "zh": "我妹妹的娃娃很可爱。"}, {"en": "The name of the school is Happy School.", "zh": "这所学校的名字是快乐学校。"}]', '["This is Tom book. （漏掉 ''s，应为 Tom''s book）", "This is Tom''s and Sam''s bag. （两个人各自的东西，两个名字后都要加 ''s）", "The room''s door is open. （无生命的东西用 of，应为 The door of the room）", "This is James''s bag. （名字以 s 结尾，只加 ''，应为 James'' bag）", "The cat tail is long. （有生命的动物要加 ''s，应为 The cat''s tail）"]', '人加 ''s，物用 of；名字带 s，只加撇。', 2, 'ai', 0, '2026-09-18 17:34:16.226419', '2026-09-21 14:52:30.895428') ON CONFLICT(id) DO UPDATE SET subject_id=excluded.subject_id, grade=excluded.grade, semester=excluded.semester, category=excluded.category, title=excluded.title, summary=excluded.summary, content_md=excluded.content_md, examples=excluded.examples, common_mistakes=excluded.common_mistakes, mnemonic=excluded.mnemonic, order_index=excluded.order_index, source=excluded.source, deleted=excluded.deleted, created_at=excluded.created_at, updated_at=excluded.updated_at;
INSERT INTO grammar_lesson (id, subject_id, grade, semester, category, title, summary, content_md, examples, common_mistakes, mnemonic, order_index, source, deleted, created_at, updated_at) VALUES (4, 2, 3, NULL, '词法·代词', '人称代词（主格与宾格）', '人称代词两副脸，做主用主格，做宾用宾格，位置不同换衣裳！', '## 这是啥

小朋友，人称代词就像我们的“名字替身”。

比如：**小明** → 用 **他** 代替。

英语里，人称代词有两套衣服：

- **主格**：当“小主人”的时候穿。
- **宾格**：当“小客人”的时候穿。

## 怎么用

### 1. 主格放在句子开头，是动作的“小主人”

谁在做事情，就用主格。

- **I** 我
- **you** 你
- **he** 他
- **she** 她
- **it** 它
- **we** 我们
- **they** 他们

例句：**I** like apples. 我喜欢苹果。

### 2. 宾格放在动词后面，是动作的“小客人”

动作落到谁身上，谁就用宾格。

- **me** 我
- **you** 你
- **him** 他
- **her** 她
- **it** 它
- **us** 我们
- **them** 他们

例句：She helps **me**. 她帮助我。

### 3. 介词后面也要用宾格

介词 like **to, for, with, at** 后面，也要用宾格。

例句：This gift is for **him**. 这个礼物是给他的。

### 4. 主格和宾格，位置不同，样子不同

同一个“我”：

- 做主：**I** am happy.
- 做宾：You like **me**.

## 小提醒

- **you** 主格和宾格长得一样，都是 you。
- **it** 主格和宾格也长得一样，都是 it。', '[{"en": "I am a student.", "zh": "我是一名学生。"}, {"en": "She is my friend.", "zh": "她是我的朋友。"}, {"en": "They play football.", "zh": "他们踢足球。"}, {"en": "He likes me.", "zh": "他喜欢我。"}, {"en": "Please help us.", "zh": "请帮助我们。"}, {"en": "This cake is for her.", "zh": "这个蛋糕是给她的。"}, {"en": "I sit with them.", "zh": "我和他们坐在一起。"}, {"en": "You can see it.", "zh": "你能看见它。"}]', '["I am 不能写成 I is", "He 后面用 is，不能写成 He are", "动词后面要用宾格，不能写 She likes I，要写 She likes me", "介词后面要用宾格，不能写 for he，要写 for him", "We 是主格，us 是宾格，不能写 They help we，要写 They help us"]', '主格前面当主人，宾格后面做客人；动词介词后，宾格来站岗！', 3, 'ai', 0, '2026-09-18 17:34:16.226419', '2026-09-21 14:52:34.603263') ON CONFLICT(id) DO UPDATE SET subject_id=excluded.subject_id, grade=excluded.grade, semester=excluded.semester, category=excluded.category, title=excluded.title, summary=excluded.summary, content_md=excluded.content_md, examples=excluded.examples, common_mistakes=excluded.common_mistakes, mnemonic=excluded.mnemonic, order_index=excluded.order_index, source=excluded.source, deleted=excluded.deleted, created_at=excluded.created_at, updated_at=excluded.updated_at;
INSERT INTO grammar_lesson (id, subject_id, grade, semester, category, title, summary, content_md, examples, common_mistakes, mnemonic, order_index, source, deleted, created_at, updated_at) VALUES (5, 2, 4, NULL, '词法·代词', '物主代词（my/your/his/her 与 mine/yours）', '我的my你的your，他的his她的her；后面带名字用my，后面不带用mine。', '## 这是啥
物主代词就是“表示东西是谁的”的小词。
比如：我的书、你的笔、他的书包。

英语里有两类：
- **后面要带东西**：my（我的）、your（你的）、his（他的）、her（她的）
- **后面不带东西**：mine（我的）、yours（你的）

## 怎么用

### 1. my / your / his / her 后面一定要跟一个东西
- 规则：my book（我的书），your pen（你的笔），his bag（他的包），her cat（她的猫）。
- 例句：This is my ruler. 这是我的尺子。

### 2. mine / yours 后面不跟东西，自己就能用
- 规则：mine = my + 东西，yours = your + 东西。
- 例句：This book is mine. 这本书是我的。

### 3. 问“是谁的”用 Whose
- 规则：Whose + 东西 + is this? 回答用 mine / yours / his / hers。
- 例句：Whose pen is this? It''s mine. 这是谁的笔？是我的。

### 4. his 和 her 要分男女
- 规则：男生用 his，女生用 her。
- 例句：This is his ball. 这是他的球。 That is her doll. 那是她的娃娃。

## 小提醒
- my 不能单独用，要说 my book。
- mine 不能加东西，不能说 mine book。
- your 和 yours 不一样：your 后面加东西，yours 自己用。', '[{"en": "This is my pencil.", "zh": "这是我的铅笔。"}, {"en": "Is that your eraser?", "zh": "那是你的橡皮吗？"}, {"en": "This is his schoolbag.", "zh": "这是他的书包。"}, {"en": "That is her kite.", "zh": "那是她的风筝。"}, {"en": "The red pen is mine.", "zh": "那支红笔是我的。"}, {"en": "The blue ruler is yours.", "zh": "那把蓝尺子是你的。"}, {"en": "Whose book is this? It''s mine.", "zh": "这是谁的书？是我的。"}, {"en": "Whose cat is that? It''s hers.", "zh": "那是谁的猫？是她的。"}]', '["把 my 单独用，说 This is my. 应该是 This is mine.", "把 mine 后面加东西，说 mine book。应该是 my book。", "把 your 和 yours 弄混，说 This is your. 应该是 This is yours.", "男生女生不分，说 This is her ball 来指男生的球。应该是 his ball。", "回答 Whose 问题时，说 It''s my. 应该是 It''s mine."]', '我的my你的your，他的his她的her；后面带东西用my，后面不带用mine；你的your要带东西，不带东西用yours。', 4, 'ai', 0, '2026-09-18 17:34:16.226419', '2026-09-21 14:52:41.488689') ON CONFLICT(id) DO UPDATE SET subject_id=excluded.subject_id, grade=excluded.grade, semester=excluded.semester, category=excluded.category, title=excluded.title, summary=excluded.summary, content_md=excluded.content_md, examples=excluded.examples, common_mistakes=excluded.common_mistakes, mnemonic=excluded.mnemonic, order_index=excluded.order_index, source=excluded.source, deleted=excluded.deleted, created_at=excluded.created_at, updated_at=excluded.updated_at;
INSERT INTO grammar_lesson (id, subject_id, grade, semester, category, title, summary, content_md, examples, common_mistakes, mnemonic, order_index, source, deleted, created_at, updated_at) VALUES (6, 2, 3, NULL, '词法·代词', '指示代词（this/that/these/those）', '近的用 this/these，远的用 that/those；一个用 this/that，多个用 these/those。', '## 这是啥

小朋友们，看这里！

- **this** 和 **these** 是「近的」：离你近的东西。
- **that** 和 **those** 是「远的」：离你远的东西。
- **this** 和 **that** 是「一个」：单数。
- **these** 和 **those** 是「多个」：复数。

就像你手里拿的苹果是 this apple，天上飞的鸟是 that bird。

## 怎么用

### 1. 近的一个：this

离你近的、只有一个东西，用 **this**。

- 例：**This** is my pen. 这是我的钢笔。

### 2. 远的一个：that

离你远的、只有一个东西，用 **that**。

- 例：**That** is your school. 那是你的学校。

### 3. 近的多个：these

离你近的、有两个或更多东西，用 **these**。

- 例：**These** are my books. 这些是我的书。

### 4. 远的多个：those

离你远的、有两个或更多东西，用 **those**。

- 例：**Those** are birds. 那些是鸟。

## 小提醒

- this/that 后面跟 **is**。
- these/those 后面跟 **are**。
- 说的时候，用手指一指，近的点点，远的指指，就不会错啦！', '[{"en": "This is my bag.", "zh": "这是我的书包。"}, {"en": "That is a cat.", "zh": "那是一只猫。"}, {"en": "These are my pencils.", "zh": "这些是我的铅笔。"}, {"en": "Those are apples.", "zh": "那些是苹果。"}, {"en": "This is a red apple.", "zh": "这是一个红苹果。"}, {"en": "That is your desk.", "zh": "那是你的书桌。"}, {"en": "These are my friends.", "zh": "这些是我的朋友。"}, {"en": "Those are big trees.", "zh": "那些是大树。"}]', '["This are my books. 应改成 These are my books.", "These is my pen. 应改成 This is my pen.", "That are birds. 应改成 Those are birds.", "Those is apples. 应改成 Those are apples.", "This is my books. 应改成 These are my books."]', '近 this/these，远 that/those；一个 is，多个 are，指一指就不会错！', 5, 'ai', 0, '2026-09-18 17:34:16.226419', '2026-09-21 14:52:37.482468') ON CONFLICT(id) DO UPDATE SET subject_id=excluded.subject_id, grade=excluded.grade, semester=excluded.semester, category=excluded.category, title=excluded.title, summary=excluded.summary, content_md=excluded.content_md, examples=excluded.examples, common_mistakes=excluded.common_mistakes, mnemonic=excluded.mnemonic, order_index=excluded.order_index, source=excluded.source, deleted=excluded.deleted, created_at=excluded.created_at, updated_at=excluded.updated_at;
INSERT INTO grammar_lesson (id, subject_id, grade, semester, category, title, summary, content_md, examples, common_mistakes, mnemonic, order_index, source, deleted, created_at, updated_at) VALUES (7, 2, 4, NULL, '词法·代词', '疑问代词（what/who/whose/which）', '问东西用 what，问人用 who，问谁的用 whose，选一选用 which。', '## 这是啥
疑问代词就是用来问问题的词，像小侦探一样，帮我们找到答案。

## 怎么用
### 1. what 问东西
问“什么”的时候用 what。
- 例句：What is this? 这是什么？

### 2. who 问人
问“谁”的时候用 who。
- 例句：Who is she? 她是谁？

### 3. whose 问谁的
问“谁的”的时候用 whose。
- 例句：Whose book is this? 这是谁的书？

### 4. which 选一选
问“哪一个”的时候用 which。
- 例句：Which is your bag? 哪个是你的包？

## 小提醒
- what 问东西，who 问人，whose 问主人，which 做选择。
- 它们都放在句子开头，后面跟 is/are 或名词。', '[{"en": "What is your name?", "zh": "你叫什么名字？"}, {"en": "Who is your teacher?", "zh": "谁是你的老师？"}, {"en": "Whose pen is this?", "zh": "这是谁的钢笔？"}, {"en": "Which is your desk?", "zh": "哪个是你的桌子？"}, {"en": "What color is your bag?", "zh": "你的包是什么颜色？"}, {"en": "Who is that boy?", "zh": "那个男孩是谁？"}, {"en": "Whose shoes are these?", "zh": "这些是谁的鞋子？"}, {"en": "Which one do you like?", "zh": "你喜欢哪一个？"}]', '["What is your name? 不能写成 Who is your name?", "Whose book is this? 不能写成 Who book is this?", "Which is your bag? 不能写成 What is your bag?", "Who is she? 不能写成 What is she?（问人用 who）", "Whose 后面要跟名词，如 Whose pen，不能单独用 Whose is this?"]', 'what 问物 who 问人，whose 问谁的要记清，which 来把选择定，四个代词要分清。', 6, 'ai', 0, '2026-09-18 17:34:16.226419', '2026-09-21 14:52:44.641152') ON CONFLICT(id) DO UPDATE SET subject_id=excluded.subject_id, grade=excluded.grade, semester=excluded.semester, category=excluded.category, title=excluded.title, summary=excluded.summary, content_md=excluded.content_md, examples=excluded.examples, common_mistakes=excluded.common_mistakes, mnemonic=excluded.mnemonic, order_index=excluded.order_index, source=excluded.source, deleted=excluded.deleted, created_at=excluded.created_at, updated_at=excluded.updated_at;
INSERT INTO grammar_lesson (id, subject_id, grade, semester, category, title, summary, content_md, examples, common_mistakes, mnemonic, order_index, source, deleted, created_at, updated_at) VALUES (8, 2, 3, NULL, '词法·动词', 'be 动词（am/is/are）的用法', '我配am，你配are，is跟着他她它，复数全都用are。', '## 这是啥

be 动词就是英语里的「是」。

它有三个小兄弟：**am、is、are**。

它们都表示「是」，但要用对地方哦！

## 怎么用

### 1. 我 用 am

**I** 后面永远跟 **am**。

例句：I am happy. 我很开心。

### 2. 你 用 are

**You** 后面永远跟 **are**。

例句：You are my friend. 你是我的朋友。

### 3. 他她它 用 is

**He、She、It** 后面跟 **is**。

例句：She is a teacher. 她是一名老师。

### 4. 复数 用 are

两个或两个以上的人或东西，用 **are**。

例句：We are students. 我们是学生。

## 小提醒

- 记住：**我 am，你 are，is 跟着他她它**。
- 复数（我们、你们、他们、很多个东西）都用 **are**。', '[{"en": "I am a student.", "zh": "我是一名学生。"}, {"en": "I am nine years old.", "zh": "我九岁了。"}, {"en": "You are my good friend.", "zh": "你是我的好朋友。"}, {"en": "You are very kind.", "zh": "你非常善良。"}, {"en": "He is my brother.", "zh": "他是我的哥哥。"}, {"en": "She is a doctor.", "zh": "她是一名医生。"}, {"en": "It is a cat.", "zh": "它是一只猫。"}, {"en": "We are in the classroom.", "zh": "我们在教室里。"}]', '["I 后面不能用 is，要说 I am", "You 后面不能用 am，要说 You are", "He、She、It 后面不能用 are，要说 He is、She is、It is", "复数（we、you、they）后面不能用 is，要说 We are、They are", "不能把 am、is、are 丢掉，比如不能说 I happy，要说 I am happy"]', '我 am，你 are，is 跟着他她它；复数全都用 are，千万别搞差！', 7, 'ai', 0, '2026-09-18 17:34:16.226419', '2026-09-18 17:34:41.028322') ON CONFLICT(id) DO UPDATE SET subject_id=excluded.subject_id, grade=excluded.grade, semester=excluded.semester, category=excluded.category, title=excluded.title, summary=excluded.summary, content_md=excluded.content_md, examples=excluded.examples, common_mistakes=excluded.common_mistakes, mnemonic=excluded.mnemonic, order_index=excluded.order_index, source=excluded.source, deleted=excluded.deleted, created_at=excluded.created_at, updated_at=excluded.updated_at;
INSERT INTO grammar_lesson (id, subject_id, grade, semester, category, title, summary, content_md, examples, common_mistakes, mnemonic, order_index, source, deleted, created_at, updated_at) VALUES (9, 2, 4, NULL, '词法·动词', '一般现在时与动词三单', '一般现在时，经常做的事；主语是he、she、it，动词后面加s或es。', '## 这是啥

小朋友们，一般现在时就是说**经常做的事**、**每天做的事**。

比如：
- 我每天上学。
- 他喜欢苹果。
- 小猫喝牛奶。

这些事不是只做一次，而是**常常做**，就要用一般现在时。

## 怎么用

### 要点1：I、you、we、they 后面，动词用原形

主语是 **I / you / we / they** 的时候，动词不用变，直接用原形。

例子：
- I **play** football. 我踢足球。
- You **like** apples. 你喜欢苹果。
- We **go** to school. 我们去上学。

### 要点2：he、she、it 后面，动词要加 s

主语是 **he / she / it**，或者一个人名（比如 Tom），动词后面要加 **s**。

例子：
- He **plays** football. 他踢足球。
- She **likes** apples. 她喜欢苹果。
- Tom **goes** to school. 汤姆去上学。

### 要点3：动词以 s、x、ch、sh、o 结尾，加 es

有些动词不能只加 s，要加 **es**。

例子：
- He **watches** TV. 他看电视。
- She **goes** to school. 她去上学。
- My mom **washes** clothes. 我妈妈洗衣服。

### 要点4：动词以辅音字母 + y 结尾，把 y 变 i 再加 es

比如 study 变成 studies，fly 变成 flies。

例子：
- He **studies** English. 他学英语。
- The bird **flies**. 鸟飞。

## 小提醒

主语是 he、she、it 时，动词要变身，这叫**动词三单**。

记住：**他她它，动词加 s 或 es！**', '[{"en": "I play football.", "zh": "我踢足球。"}, {"en": "You like apples.", "zh": "你喜欢苹果。"}, {"en": "We go to school.", "zh": "我们去上学。"}, {"en": "He plays football.", "zh": "他踢足球。"}, {"en": "She likes apples.", "zh": "她喜欢苹果。"}, {"en": "Tom goes to school.", "zh": "汤姆去上学。"}, {"en": "He watches TV.", "zh": "他看电视。"}, {"en": "She studies English.", "zh": "她学英语。"}]', '["He play football. 错啦！he 后面要加 s，应该是 He plays football.", "She like apples. 错啦！she 后面要加 s，应该是 She likes apples.", "Tom go to school. 错啦！Tom 是第三人称单数，应该是 Tom goes to school.", "He watch TV. 错啦！watch 要加 es，应该是 He watches TV.", "He study English. 错啦！study 要变 studies，应该是 He studies English."]', '我你我们他们，动词原形不变身；他她它，动词后面加 s 或 es！', 8, 'ai', 0, '2026-09-18 17:34:16.226419', '2026-09-21 14:52:52.230104') ON CONFLICT(id) DO UPDATE SET subject_id=excluded.subject_id, grade=excluded.grade, semester=excluded.semester, category=excluded.category, title=excluded.title, summary=excluded.summary, content_md=excluded.content_md, examples=excluded.examples, common_mistakes=excluded.common_mistakes, mnemonic=excluded.mnemonic, order_index=excluded.order_index, source=excluded.source, deleted=excluded.deleted, created_at=excluded.created_at, updated_at=excluded.updated_at;
INSERT INTO grammar_lesson (id, subject_id, grade, semester, category, title, summary, content_md, examples, common_mistakes, mnemonic, order_index, source, deleted, created_at, updated_at) VALUES (10, 2, 4, NULL, '词法·动词', '现在进行时（be + doing）', '现在进行时，be加doing，正在做的事，一眼就看明！', '## 这是啥

小朋友们，现在进行时就是用来告诉别人：**此时此刻，正在做某件事**。

比如：
- 你正在看书 → I am reading.
- 妈妈正在做饭 → Mom is cooking.

就像拍照片一样，把“正在发生”的动作拍下来！

## 怎么用

### 要点1：be动词不能少

**规则**：主语 + be动词 + 动词ing

**例句**：I **am** eating an apple. （我正在吃苹果。）

### 要点2：be动词要跟主语配对

**规则**：
- I 用 **am**
- He / She / It 用 **is**
- You / We / They 用 **are**

**例句**：She **is** singing. （她正在唱歌。）

### 要点3：动词后面加ing

**规则**：动词后面直接加 **ing**。

**例句**：They **are** play**ing** football. （他们正在踢足球。）

### 要点4：表示“现在”的时间词

**规则**：常和 now, look, listen 一起用。

**例句**：Look! The cat **is** runn**ing**. （看！猫正在跑。）

## 小提醒

- 别忘记 be 动词！
- 动词 ing 别写错哦！
- 主语和 be 动词要配对！', '[{"en": "I am reading a book.", "zh": "我正在看书。"}, {"en": "She is singing a song.", "zh": "她正在唱歌。"}, {"en": "They are playing football.", "zh": "他们正在踢足球。"}, {"en": "Look! The cat is running.", "zh": "看！猫正在跑。"}, {"en": "We are eating lunch now.", "zh": "我们现在正在吃午饭。"}, {"en": "He is drawing a picture.", "zh": "他正在画画。"}, {"en": "Listen! The birds are singing.", "zh": "听！鸟儿正在唱歌。"}]', '["I am 不能写成 I is，I 只能配 am", "He/She/It 后面要用 is，不能用 are", "动词ing 不能忘记加，比如 I am read 是错的，要写 I am reading", "主语是复数时，be动词要用 are，比如 They is 是错的，要写 They are", "现在进行时不能丢掉 be 动词，比如 I reading 是错的，要写 I am reading"]', '现在进行时，be加ing，I配am，你配are，他她它配is，动词后面ing，正在做事记得清！', 9, 'ai', 0, '2026-09-18 17:34:16.226419', '2026-09-21 14:52:55.797511') ON CONFLICT(id) DO UPDATE SET subject_id=excluded.subject_id, grade=excluded.grade, semester=excluded.semester, category=excluded.category, title=excluded.title, summary=excluded.summary, content_md=excluded.content_md, examples=excluded.examples, common_mistakes=excluded.common_mistakes, mnemonic=excluded.mnemonic, order_index=excluded.order_index, source=excluded.source, deleted=excluded.deleted, created_at=excluded.created_at, updated_at=excluded.updated_at;
INSERT INTO grammar_lesson (id, subject_id, grade, semester, category, title, summary, content_md, examples, common_mistakes, mnemonic, order_index, source, deleted, created_at, updated_at) VALUES (11, 2, 5, NULL, '词法·动词', '一般过去时（规则与不规则过去式）', '过去的事，动词要变身：规则加-ed，不规则要记牢！', '## 这是啥

小朋友们，你们有没有讲过昨天发生的事呀？

比如：

- 昨天我玩得很开心。
- 上周我去了公园。

这些事情都是**过去**发生的。

在英语里，讲过去的事情，动词要“变身”！

这个“变身”就叫 **一般过去时**。

## 怎么用

### 要点1：规则动词，直接加 -ed

大多数动词，在后面加上 **-ed** 就行啦！

- play → played
- watch → watched
- clean → cleaned

**例句：**

I played football yesterday.
我昨天踢了足球。

### 要点2：以 e 结尾，只加 -d

如果动词本身以字母 **e** 结尾，只要加 **-d** 就好。

- like → liked
- dance → danced

**例句：**

She danced with her friends last night.
她昨晚和朋友们跳舞了。

### 要点3：辅音字母 + y 结尾，变 y 为 i 再加 -ed

如果动词是“辅音字母 + y”结尾，要把 **y 变成 i**，再加 **-ed**。

- study → studied
- carry → carried

**例句：**

He studied English this morning.
他今天早上学了英语。

### 要点4：不规则动词，要特别记

有些动词很调皮，不按规则来，我们要把它们记在小脑袋里！

- go → went
- eat → ate
- see → saw
- have → had
- do → did

**例句：**

I went to the zoo last Sunday.
我上周日去了动物园。

## 小提醒

一般过去时常常和这些词一起出现：

- yesterday（昨天）
- last week（上周）
- two days ago（两天前）

看到它们，就要想到动词要“变身”哦！', '[{"en": "I played football yesterday.", "zh": "我昨天踢了足球。"}, {"en": "She danced with her friends last night.", "zh": "她昨晚和朋友们跳舞了。"}, {"en": "He studied English this morning.", "zh": "他今天早上学了英语。"}, {"en": "I went to the zoo last Sunday.", "zh": "我上周日去了动物园。"}, {"en": "We ate noodles for lunch.", "zh": "我们午饭吃了面条。"}, {"en": "She saw a big elephant.", "zh": "她看见了一头大象。"}, {"en": "They had a good time.", "zh": "他们玩得很开心。"}, {"en": "I did my homework two hours ago.", "zh": "我两小时前做了作业。"}]', '["I go to school yesterday. 应改成 I went to school yesterday.", "She play football last week. 应改成 She played football last week.", "He studyed English. 应改成 He studied English.", "I see a cat yesterday. 应改成 I saw a cat yesterday.", "We eat noodles last night. 应改成 We ate noodles last night."]', '过去事情动词变，规则加-ed记心间；不规则要单独记，go-went，eat-ate，see-saw！', 10, 'ai', 0, '2026-09-18 17:34:16.226419', '2026-09-21 14:52:59.835431') ON CONFLICT(id) DO UPDATE SET subject_id=excluded.subject_id, grade=excluded.grade, semester=excluded.semester, category=excluded.category, title=excluded.title, summary=excluded.summary, content_md=excluded.content_md, examples=excluded.examples, common_mistakes=excluded.common_mistakes, mnemonic=excluded.mnemonic, order_index=excluded.order_index, source=excluded.source, deleted=excluded.deleted, created_at=excluded.created_at, updated_at=excluded.updated_at;
INSERT INTO grammar_lesson (id, subject_id, grade, semester, category, title, summary, content_md, examples, common_mistakes, mnemonic, order_index, source, deleted, created_at, updated_at) VALUES (12, 2, 5, NULL, '词法·动词', '一般将来时（will 与 be going to）', '将来事，will 来帮忙，计划好，be going to 上！', '## 这是啥

小朋友们，你们有没有想过明天、下周、明年要做什么呀？

比如：
- 明天我要去公园。
- 下周我们要考试。
- 明年我就要上六年级啦！

这些事情都还没发生，是**将来**要发生的。英语里，说将来的事情，就要用**一般将来时**。

一般将来时有两个好帮手：
1. **will**
2. **be going to**

它们就像两辆小汽车，都能带我们去“将来”！

## 怎么用

### 要点1：will + 动词原形

**规则**：will 后面永远跟动词原形，不管主语是谁，will 都不变。

**公式**：主语 + will + 动词原形

**例句**：I will play football tomorrow. （我明天要踢足球。）

### 要点2：be going to + 动词原形

**规则**：be 动词要跟着主语变（am / is / are），going to 后面跟动词原形。

**公式**：主语 + am/is/are + going to + 动词原形

**例句**：She is going to visit her grandma. （她打算去看望她的奶奶。）

### 要点3：will 和 be going to 的小区别

**规则**：
- **will**：表示说话时临时决定，或者单纯预测将来。
- **be going to**：表示早就计划好、打算要做的事。

**例句**：
- The phone is ringing. I will answer it. （电话响了，我去接。——临时决定）
- I am going to buy a book this weekend. （我这周末打算去买本书。——早就计划好了）

### 要点4：否定和疑问很简单

**规则**：
- will 的否定：will not = won''t
- be going to 的否定：在 be 后面加 not
- 疑问句：把 will 或 be 提到句子最前面

**例句**：
- I won''t tell anyone. （我不会告诉任何人。）
- Are you going to play basketball? （你打算去打篮球吗？）

## 小提醒

- will 和 be going to 后面都跟**动词原形**，千万别加 s 或 ed！
- be going to 里的 be 动词，一定要和主语搭配好：I 用 am，he/she/it 用 is，you/we/they 用 are。', '[{"en": "I will help you with your homework.", "zh": "我会帮你做作业。"}, {"en": "She is going to learn to swim this summer.", "zh": "她打算今年夏天学游泳。"}, {"en": "They will come to my birthday party.", "zh": "他们会来参加我的生日派对。"}, {"en": "We are going to have a picnic on Sunday.", "zh": "我们打算周日去野餐。"}, {"en": "It will rain tomorrow.", "zh": "明天会下雨。"}, {"en": "He is not going to watch TV tonight.", "zh": "他今晚不打算看电视。"}, {"en": "Will you go to the zoo with me?", "zh": "你愿意和我一起去动物园吗？"}, {"en": "I am going to be a teacher when I grow up.", "zh": "我长大后打算当一名老师。"}]', '["will 后面加了动词的过去式或 ing 形式，比如写成 will played 或 will playing，应该用动词原形 will play。", "be going to 里的 be 动词用错，比如 He are going to... 应该是 He is going to...", "把 will 和 be going to 混在一起用，比如写成 I will going to... 这是不对的，只能选一个。", "否定句里 won''t 后面又加了 not，比如 I won''t not go. 应该是 I won''t go.", "疑问句忘记把 will 或 be 提到句首，比如写成 You will go? 应该是 Will you go?"]', '将来事情还没做，will 和 be going to 来掌舵；will 后动词用原形，be 要跟着主语变；计划打算用 going to，临时决定 will 来担！', 11, 'ai', 0, '2026-09-18 17:34:16.226419', '2026-09-21 14:53:05.030692') ON CONFLICT(id) DO UPDATE SET subject_id=excluded.subject_id, grade=excluded.grade, semester=excluded.semester, category=excluded.category, title=excluded.title, summary=excluded.summary, content_md=excluded.content_md, examples=excluded.examples, common_mistakes=excluded.common_mistakes, mnemonic=excluded.mnemonic, order_index=excluded.order_index, source=excluded.source, deleted=excluded.deleted, created_at=excluded.created_at, updated_at=excluded.updated_at;
INSERT INTO grammar_lesson (id, subject_id, grade, semester, category, title, summary, content_md, examples, common_mistakes, mnemonic, order_index, source, deleted, created_at, updated_at) VALUES (13, 2, 3, NULL, '词法·动词', '情态动词 can', '情态动词 can，本事大无边，后面跟动词，原形不变脸。', '## 这是啥

小朋友，can 就像你手里的魔法棒！

- 说「我会……」「我能……」的时候，就用 can。
- can 后面永远跟着一个动词，而且这个动词要穿「原形」衣服，不能加 s，不能加 ing。

比如：
- I can swim. 我会游泳。
- She can sing. 她会唱歌。

## 怎么用

### 1. 说「我会做某事」

规则：**人 + can + 动词原形**

例句：
- I can jump. 我会跳。

### 2. 说「他不会做某事」

规则：**人 + can not (can''t) + 动词原形**

例句：
- He can''t dance. 他不会跳舞。

### 3. 问「你会做某事吗？」

规则：**Can + 人 + 动词原形？**

回答：
- Yes, I can. 是的，我会。
- No, I can''t. 不，我不会。

例句：
- Can you draw? 你会画画吗？

### 4. 不管是谁，can 都不变

规则：**I / you / he / she / it / we / they 后面都用 can**

例句：
- She can read. 她会读书。
- They can run. 他们会跑。

## 小提醒

- can 后面不要加 to。
- can 后面动词不加 s。
- can''t 是 can not 的缩写，读 /kɑːnt/。', '[{"en": "I can swim.", "zh": "我会游泳。"}, {"en": "She can sing.", "zh": "她会唱歌。"}, {"en": "He can''t dance.", "zh": "他不会跳舞。"}, {"en": "Can you draw?", "zh": "你会画画吗？"}, {"en": "Yes, I can.", "zh": "是的，我会。"}, {"en": "No, I can''t.", "zh": "不，我不会。"}, {"en": "They can run.", "zh": "他们会跑。"}, {"en": "We can read.", "zh": "我们会读书。"}]', '["I can to swim. 错！can 后面不加 to，应该是 I can swim.", "She can sings. 错！can 后面动词不加 s，应该是 She can sing.", "He can swimming. 错！can 后面动词用原形，应该是 He can swim.", "Can you to draw? 错！问句里 can 后面也不加 to，应该是 Can you draw?", "I can''t not swim. 错！can''t 已经表示「不会」，不用再加 not，应该是 I can''t swim."]', '情态动词 can，后面跟动原；否定加 not，问句 can 提前。', 12, 'ai', 0, '2026-09-18 17:34:16.226419', '2026-09-21 14:52:48.471414') ON CONFLICT(id) DO UPDATE SET subject_id=excluded.subject_id, grade=excluded.grade, semester=excluded.semester, category=excluded.category, title=excluded.title, summary=excluded.summary, content_md=excluded.content_md, examples=excluded.examples, common_mistakes=excluded.common_mistakes, mnemonic=excluded.mnemonic, order_index=excluded.order_index, source=excluded.source, deleted=excluded.deleted, created_at=excluded.created_at, updated_at=excluded.updated_at;
INSERT INTO grammar_lesson (id, subject_id, grade, semester, category, title, summary, content_md, examples, common_mistakes, mnemonic, order_index, source, deleted, created_at, updated_at) VALUES (14, 2, 3, NULL, '词法·形副', '形容词的用法', '形容词，形容词，放在名词前，说明它啥样，be动词后也常见！', '## 这是啥
形容词就是「形容」一个东西的词。

它告诉我们：这个东西是**大**还是**小**，是**红**还是**蓝**，是**开心**还是**难过**。

比如：
- a **big** ball（一个大球）
- a **red** apple（一个红苹果）
- I am **happy**.（我很开心。）

## 怎么用

### 要点1：形容词放在名词前面
形容词就像名词的「小帽子」，戴在名词前面。

- 例子：I have a **cute** dog. （我有一只可爱的狗。）

### 要点2：形容词也可以放在 be 动词后面
be 动词（am / is / are）后面也可以放形容词，说明主语怎么样。

- 例子：The cat is **fat**. （这只猫很胖。）

### 要点3：形容词不用变来变去
不管前面是 a、an，还是 the，形容词本身都不变。

- 例子：a **small** car / the **small** car （一辆小车 / 那辆小车）

### 要点4：形容词可以叠用
一个名词前面可以放两个形容词，顺序一般是「大小 + 颜色」。

- 例子：a **big red** balloon （一个红色的大气球）', '[{"en": "I have a big ball.", "zh": "我有一个大球。"}, {"en": "She is a happy girl.", "zh": "她是一个快乐的女孩。"}, {"en": "The dog is cute.", "zh": "这只狗很可爱。"}, {"en": "My bag is new.", "zh": "我的书包是新的。"}, {"en": "Look at the small cat.", "zh": "看那只小猫。"}, {"en": "This is a red apple.", "zh": "这是一个红苹果。"}, {"en": "He is tall.", "zh": "他很高。"}, {"en": "I see a big red balloon.", "zh": "我看见一个红色的大气球。"}]', '["形容词放在名词后面，比如把 a red apple 说成 a apple red", "be 动词后面忘了加形容词，比如把 I am happy 说成 I happy", "形容词前面乱加 a，比如把 She is happy 说成 She is a happy", "两个形容词顺序搞反，比如把 a big red ball 说成 a red big ball", "把形容词和副词搞混，比如把 He is quick 说成 He is quickly"]', '形容词，真能干，名词前面站一站；be动词后也常见，说明样子和情感！', 13, 'ai', 0, '2026-09-18 17:34:16.226419', '2026-09-21 14:53:08.707885') ON CONFLICT(id) DO UPDATE SET subject_id=excluded.subject_id, grade=excluded.grade, semester=excluded.semester, category=excluded.category, title=excluded.title, summary=excluded.summary, content_md=excluded.content_md, examples=excluded.examples, common_mistakes=excluded.common_mistakes, mnemonic=excluded.mnemonic, order_index=excluded.order_index, source=excluded.source, deleted=excluded.deleted, created_at=excluded.created_at, updated_at=excluded.updated_at;
INSERT INTO grammar_lesson (id, subject_id, grade, semester, category, title, summary, content_md, examples, common_mistakes, mnemonic, order_index, source, deleted, created_at, updated_at) VALUES (15, 2, 4, NULL, '词法·形副', '副词的用法（修饰动词）', '副词副词真能干，跟在动词后面转，说明“怎样”做事情，动作样子它来管！', '## 这是啥
小朋友们，副词就像动词的“小跟班”。
它告诉我们：这个动作是**怎样**做的。
比如：run（跑）——run **fast**（跑得快）。
fast 就是副词，它让“跑”变得更清楚啦！

## 怎么用
### 1. 副词常常放在动词后面
规则：先说动词，再说副词。
例句：She sings **beautifully**. 她唱得很动听。

### 2. 副词可以说明“怎样做”
规则：副词回答“How?”（怎样？）
例句：He walks **slowly**. 他走得慢。

### 3. 很多副词是形容词加 -ly 变来的
规则：形容词 + ly = 副词。
例句：quick（快的）→ **quickly**（快地）
例句：The rabbit runs **quickly**. 兔子跑得快。

### 4. 有些副词和形容词长得一样
规则：fast、hard 等词，形容词和副词同形。
例句：He is a **fast** runner.（形容词）
例句：He runs **fast**.（副词）

## 小提醒
副词是来帮忙的，不是来当主角的。
它让句子更生动，就像给动作画上颜色！', '[{"en": "She sings beautifully.", "zh": "她唱得很动听。"}, {"en": "He walks slowly.", "zh": "他走得慢。"}, {"en": "The rabbit runs quickly.", "zh": "兔子跑得快。"}, {"en": "They dance happily.", "zh": "他们开心地跳舞。"}, {"en": "He runs fast.", "zh": "他跑得快。"}, {"en": "She studies hard.", "zh": "她学习努力。"}, {"en": "The turtle moves slowly.", "zh": "乌龟慢慢地移动。"}]', '["She sings beautiful. 应改成 She sings beautifully.（修饰动词要用副词）", "He runs quick. 应改成 He runs quickly.（形容词 quick 要加 -ly 变副词）", "I am run fast. 应改成 I run fast.（run 是动词，前面不用 am）", "She dances good. 应改成 She dances well.（good 是形容词，well 才是副词）", "He plays the piano very good. 应改成 He plays the piano very well.（修饰动词用 well）"]', '副词副词跟动词，说明怎样做事情；形容词加 -ly，动作样子更分明！', 14, 'ai', 0, '2026-09-18 17:34:16.226419', '2026-09-21 14:53:12.548701') ON CONFLICT(id) DO UPDATE SET subject_id=excluded.subject_id, grade=excluded.grade, semester=excluded.semester, category=excluded.category, title=excluded.title, summary=excluded.summary, content_md=excluded.content_md, examples=excluded.examples, common_mistakes=excluded.common_mistakes, mnemonic=excluded.mnemonic, order_index=excluded.order_index, source=excluded.source, deleted=excluded.deleted, created_at=excluded.created_at, updated_at=excluded.updated_at;
INSERT INTO grammar_lesson (id, subject_id, grade, semester, category, title, summary, content_md, examples, common_mistakes, mnemonic, order_index, source, deleted, created_at, updated_at) VALUES (16, 2, 5, NULL, '词法·形副', '形容词比较级（er / more）', '比较级，比一比：短词加er，长词加more，than在后面跟着走！', '## 这是啥

小朋友，你有没有比过谁更高、谁跑得更快？

英语里，要把两个东西比一比，就要用 **比较级**。

比如：
- 我比你高。 → I am **taller** than you.
- 这个苹果比那个大。 → This apple is **bigger** than that one.

比较级就是“更……”的意思。

## 怎么用

### 要点1：短单词，直接加 er

**规则**：大多数短单词（1个音节），后面直接加 **er**。

**例子**：
- tall（高）→ **taller**（更高）
- 我爸爸比我妈妈高。 → My dad is **taller** than my mom.

### 要点2：长单词，前面加 more

**规则**：长单词（3个音节或以上），前面加 **more**，单词本身不变。

**例子**：
- beautiful（漂亮）→ **more beautiful**（更漂亮）
- 这朵花比那朵花更漂亮。 → This flower is **more beautiful** than that one.

### 要点3：特殊变化，要记牢

**规则**：有些单词不按规矩来，要特别记住。

**例子**：
- good（好）→ **better**（更好）
- 我的英语比数学好。 → My English is **better** than my math.

### 要点4：比一比，要用 than

**规则**：比较级后面常常跟 **than**，表示“比……”。

**例子**：
- 我跑得比你快。 → I run **faster** than you.

## 小提醒

- 短单词加 er：tall → taller
- 长单词加 more：beautiful → more beautiful
- 特殊变化：good → better
- 别忘了 than！', '[{"en": "My dad is taller than my mom.", "zh": "我爸爸比我妈妈高。"}, {"en": "This flower is more beautiful than that one.", "zh": "这朵花比那朵花更漂亮。"}, {"en": "My English is better than my math.", "zh": "我的英语比数学好。"}, {"en": "I run faster than you.", "zh": "我跑得比你快。"}, {"en": "This book is more interesting than that book.", "zh": "这本书比那本书更有趣。"}, {"en": "My sister is younger than me.", "zh": "我妹妹比我小。"}, {"en": "The sun is bigger than the moon.", "zh": "太阳比月亮大。"}]', '["tall 的比较级写成 more tall（错），应该是 taller", "beautiful 的比较级写成 beautifuler（错），应该是 more beautiful", "good 的比较级写成 gooder（错），应该是 better", "比较级后面忘记加 than，比如 I am taller you（错），应该是 I am taller than you", "两个东西比较时，形容词忘记变比较级，比如 I am tall than you（错），应该是 I am taller than you"]', '短词加er，长词加more，特殊变化要记牢，than在后面不能少！', 15, 'ai', 0, '2026-09-18 17:34:16.226419', '2026-09-21 14:53:16.504684') ON CONFLICT(id) DO UPDATE SET subject_id=excluded.subject_id, grade=excluded.grade, semester=excluded.semester, category=excluded.category, title=excluded.title, summary=excluded.summary, content_md=excluded.content_md, examples=excluded.examples, common_mistakes=excluded.common_mistakes, mnemonic=excluded.mnemonic, order_index=excluded.order_index, source=excluded.source, deleted=excluded.deleted, created_at=excluded.created_at, updated_at=excluded.updated_at;
INSERT INTO grammar_lesson (id, subject_id, grade, semester, category, title, summary, content_md, examples, common_mistakes, mnemonic, order_index, source, deleted, created_at, updated_at) VALUES (17, 2, 6, NULL, '词法·形副', '形容词最高级（est / most）', '三者以上比一比，最高级要加est；长单词前加most，the别忘记！', '## 这是啥

小朋友们，你们好！

今天我们来学**形容词最高级**。

什么是最高级呢？

就是在一群人或东西里，找出**最**厉害的那个！

比如：

- 小明是**最高**的。
- 苹果是**最好吃**的。
- 这是**最漂亮**的花。

英语里，最高级就是用来表示“最……”的。

## 怎么用

### 要点1：短单词，直接加 est

**规则**：单词很短（一般1个音节），就在后面加 **est**。

**例子**：

- tall（高）→ tallest（最高）
- 例句：Tom is the **tallest** in our class.
- 中文：汤姆是我们班最高的。

### 要点2：长单词，前面加 most

**规则**：单词很长（一般3个音节以上），就在前面加 **most**。

**例子**：

- beautiful（漂亮）→ most beautiful（最漂亮）
- 例句：This is the **most beautiful** flower.
- 中文：这是最漂亮的花。

### 要点3：别忘了 the

**规则**：最高级前面，通常要加 **the**。

**例子**：

- 例句：She is **the** best student.
- 中文：她是最好的学生。

### 要点4：特殊变化要记牢

**规则**：有些单词不按规则变，要特别记住。

**例子**：

- good → best（最好）
- bad → worst（最差）
- 例句：This is the **best** cake.
- 中文：这是最好的蛋糕。

## 小提醒

- 最高级是“最”，不是“比较”。
- 比较级是“更”，最高级是“最”。
- 记住：**the + 最高级**。', '[{"en": "Tom is the tallest in our class.", "zh": "汤姆是我们班最高的。"}, {"en": "This is the most beautiful flower.", "zh": "这是最漂亮的花。"}, {"en": "She is the best student.", "zh": "她是最好的学生。"}, {"en": "This is the best cake.", "zh": "这是最好的蛋糕。"}, {"en": "My bag is the biggest.", "zh": "我的书包是最大的。"}, {"en": "He is the most careful boy.", "zh": "他是最仔细的男孩。"}, {"en": "Today is the hottest day.", "zh": "今天是最热的一天。"}]', '["最高级前忘记加 the，比如写成 She is best student.", "长单词前错加 est，比如写成 beautifulest。", "把比较级和最高级搞混，比如写成 He is taller in the class.", "特殊变化记错，比如把 good 的最高级写成 goodest。", "在最高级后面再加 than，比如写成 He is the tallest than me."]', '最高级，最最最，短词加est，长词加most，前面别忘the！', 16, 'ai', 0, '2026-09-18 17:34:16.226419', '2026-09-21 14:53:20.785784') ON CONFLICT(id) DO UPDATE SET subject_id=excluded.subject_id, grade=excluded.grade, semester=excluded.semester, category=excluded.category, title=excluded.title, summary=excluded.summary, content_md=excluded.content_md, examples=excluded.examples, common_mistakes=excluded.common_mistakes, mnemonic=excluded.mnemonic, order_index=excluded.order_index, source=excluded.source, deleted=excluded.deleted, created_at=excluded.created_at, updated_at=excluded.updated_at;
INSERT INTO grammar_lesson (id, subject_id, grade, semester, category, title, summary, content_md, examples, common_mistakes, mnemonic, order_index, source, deleted, created_at, updated_at) VALUES (18, 2, 3, NULL, '词法·其他', '冠词（a/an/the）', 'a/an 是「一个」，the 是「这个那个」，特指就用 the，泛指就用 a/an！', '## 这是啥

小朋友，冠词就像英语里的「小帽子」，戴在名词前面。

- **a / an**：表示「一个」，但不特别指哪一个。
- **the**：表示「这个、那个」，特指某一个。

## 怎么用

### 1. 第一次提到，用 a 或 an

第一次说一个东西，用 a 或 an。

- 例：I have **a** cat. 我有一只猫。

### 2. 元音音素前用 an

单词开头是 a、e、i、o、u 的音，就用 an。

- 例：She eats **an** apple. 她吃一个苹果。

### 3. 特指某一个，用 the

大家都知道的，或者第二次提到的，用 the。

- 例：The cat is cute. 那只猫很可爱。

### 4. 独一无二的东西，用 the

世界上只有一个的，用 the。

- 例：**The** sun is big. 太阳很大。

## 小提醒

- a 和 an 只能用在「一个」的东西前。
- the 可以用在单数、复数前面。
- 说话双方都知道是哪个，就用 the。', '[{"en": "I have a dog.", "zh": "我有一只狗。"}, {"en": "She eats an orange.", "zh": "她吃一个橘子。"}, {"en": "The dog is black.", "zh": "那只狗是黑色的。"}, {"en": "The moon is bright.", "zh": "月亮很亮。"}, {"en": "He is a boy.", "zh": "他是一个男孩。"}, {"en": "I see an elephant.", "zh": "我看见一头大象。"}, {"en": "The apple is red.", "zh": "那个苹果是红色的。"}]', '["I have a apple. 应改成 I have an apple.", "The sun is a big. 应改成 The sun is big.", "I like the cats. 如果泛指猫，应改成 I like cats.", "She is an teacher. 应改成 She is a teacher.", "Look at a moon. 应改成 Look at the moon."]', 'a/an 一个不特指，the 特指这个和那个；元音开头用 an，辅音开头用 a！', 17, 'ai', 0, '2026-09-18 17:34:16.226419', '2026-09-21 14:53:24.212185') ON CONFLICT(id) DO UPDATE SET subject_id=excluded.subject_id, grade=excluded.grade, semester=excluded.semester, category=excluded.category, title=excluded.title, summary=excluded.summary, content_md=excluded.content_md, examples=excluded.examples, common_mistakes=excluded.common_mistakes, mnemonic=excluded.mnemonic, order_index=excluded.order_index, source=excluded.source, deleted=excluded.deleted, created_at=excluded.created_at, updated_at=excluded.updated_at;
INSERT INTO grammar_lesson (id, subject_id, grade, semester, category, title, summary, content_md, examples, common_mistakes, mnemonic, order_index, source, deleted, created_at, updated_at) VALUES (19, 2, 4, NULL, '词法·其他', '介词（时间 in/on/at 与地点 in/on/under）', '时间介词：in年in月in季节，on日on周on某天，at后面跟钟点；地点介词：in在里面，on在上面，under在下面。', '## 这是啥
小朋友们，介词就像“小导游”，告诉我们**什么时候**做事情，或者**在哪里**做事情。

今天我们要认识两组小导游：
- **时间小导游**：in, on, at
- **地点小导游**：in, on, under

## 怎么用

### 时间小导游

**1. in 用在“大时间”里**
- 规则：in 后面跟**年、月、季节**，还有**早上、下午、晚上**。
- 例句：I get up at 7 o''clock **in the morning**. （我早上7点起床。）

**2. on 用在“具体某一天”**
- 规则：on 后面跟**星期几、几月几号、某天的早上/下午/晚上**。
- 例句：We have a party **on Sunday**. （我们星期天有个派对。）

**3. at 用在“小时间点”**
- 规则：at 后面跟**几点钟**，还有**中午、晚上（night）**。
- 例句：Let''s meet **at 3 o''clock**. （我们3点见吧。）

### 地点小导游

**1. in 表示“在里面”**
- 规则：in 表示在某个空间的里面。
- 例句：The cat is **in the box**. （猫在盒子里。）

**2. on 表示“在上面”**
- 规则：on 表示在某个东西的表面上。
- 例句：The book is **on the desk**. （书在桌子上。）

**3. under 表示“在下面”**
- 规则：under 表示在某个东西的正下方。
- 例句：The ball is **under the chair**. （球在椅子下面。）

## 小提醒
- 时间：**in 大，on 中，at 小**。
- 地点：**in 里，on 上，under 下**。

## 一起练一练
- I play football ___ Saturday. （答案：on）
- The pencil is ___ the bag. （答案：in）
- We have lunch ___ 12 o''clock. （答案：at）', '[{"en": "I get up at 7 o''clock in the morning.", "zh": "我早上7点起床。"}, {"en": "We have a party on Sunday.", "zh": "我们星期天有个派对。"}, {"en": "Let''s meet at 3 o''clock.", "zh": "我们3点见吧。"}, {"en": "The cat is in the box.", "zh": "猫在盒子里。"}, {"en": "The book is on the desk.", "zh": "书在桌子上。"}, {"en": "The ball is under the chair.", "zh": "球在椅子下面。"}, {"en": "My birthday is in May.", "zh": "我的生日在五月。"}, {"en": "The picture is on the wall.", "zh": "画在墙上。"}]', '["I get up at 7 o''clock in the morning. 不能说成 I get up at 7 o''clock on the morning.", "We have a party on Sunday. 不能说成 We have a party in Sunday.", "Let''s meet at 3 o''clock. 不能说成 Let''s meet in 3 o''clock.", "The cat is in the box. 不能说成 The cat is on the box.（意思不一样哦）", "The ball is under the chair. 不能说成 The ball is in the chair."]', '时间介词：in年in月in季节，on日on周on某天，at后面跟钟点；地点介词：in里on上under下，小朋友们别搞混！', 18, 'ai', 0, '2026-09-18 17:34:16.226419', '2026-09-21 14:53:36.016993') ON CONFLICT(id) DO UPDATE SET subject_id=excluded.subject_id, grade=excluded.grade, semester=excluded.semester, category=excluded.category, title=excluded.title, summary=excluded.summary, content_md=excluded.content_md, examples=excluded.examples, common_mistakes=excluded.common_mistakes, mnemonic=excluded.mnemonic, order_index=excluded.order_index, source=excluded.source, deleted=excluded.deleted, created_at=excluded.created_at, updated_at=excluded.updated_at;
INSERT INTO grammar_lesson (id, subject_id, grade, semester, category, title, summary, content_md, examples, common_mistakes, mnemonic, order_index, source, deleted, created_at, updated_at) VALUES (20, 2, 3, NULL, '词法·其他', '连词（and/but/or）', 'and 是加法，but 是转弯，or 是选择，三个小连词，句子手拉手！', '## 这是啥

小朋友，你有没有发现，说话的时候，我们常常要把两个小句子连在一起？

比如：
- 我喜欢苹果。我喜欢香蕉。
- 变成：我喜欢苹果 **and** 香蕉。

这里的 **and**、**but**、**or** 就是「连词小帮手」！

它们像小胶水，把两个小句子粘在一起，让话说得更顺、更短。

## 怎么用

### 1. and：表示「和」「还有」

**规则：** 两样东西都要，就用 **and**。

**例句：**
- I like cats **and** dogs.  
  我喜欢猫和狗。

### 2. but：表示「但是」「可是」

**规则：** 前面说一个意思，后面意思不一样，就用 **but**。

**例句：**
- I am small **but** strong.  
  我个子小，但是很强壮。

### 3. or：表示「或者」「还是」

**规则：** 两个里面选一个，就用 **or**。

**例句：**
- Do you want milk **or** juice?  
  你想要牛奶还是果汁？

### 4. 小提醒

- **and** 和 **or** 可以连两个词，也可以连两个句子。
- **but** 常常连两个句子，表示「不一样」。
- 连词前面一般不加逗号，简单句子直接写就好。

## 小练习

读一读，想一想：

- I have a pen **and** a book.  
  我有一支笔和一本书。
- She is tired **but** happy.  
  她很累，但是很开心。
- Is it a cat **or** a dog?  
  它是猫还是狗？', '[{"en": "I like apples and bananas.", "zh": "我喜欢苹果和香蕉。"}, {"en": "He is short but fast.", "zh": "他个子矮，但是跑得快。"}, {"en": "Do you want tea or milk?", "zh": "你想要茶还是牛奶？"}, {"en": "My mom and I go to the park.", "zh": "我和妈妈去公园。"}, {"en": "It is cold but sunny today.", "zh": "今天很冷，但是阳光很好。"}, {"en": "Is this your book or her book?", "zh": "这是你的书还是她的书？"}, {"en": "I can sing and dance.", "zh": "我会唱歌和跳舞。"}, {"en": "I am tired but I am happy.", "zh": "我很累，但是我很开心。"}]', '["I like cats and dogs. 不能写成 I like cats or dogs.（两个都要用 and）", "Do you want tea and milk? 不能写成 Do you want tea and milk?（二选一要用 or）", "He is small but strong. 不能写成 He is small and strong.（意思相反才用 but）", "I am happy and I am tired. 不能写成 I am happy but I am tired.（如果两个都是好的，用 and）", "连词前后不能少词：I like apples and bananas. 不能写成 I like apples and banana."]', 'and 是加法，but 是转弯，or 是选择，三个小连词，句子手拉手！', 19, 'ai', 0, '2026-09-18 17:34:16.226419', '2026-09-21 14:53:28.574751') ON CONFLICT(id) DO UPDATE SET subject_id=excluded.subject_id, grade=excluded.grade, semester=excluded.semester, category=excluded.category, title=excluded.title, summary=excluded.summary, content_md=excluded.content_md, examples=excluded.examples, common_mistakes=excluded.common_mistakes, mnemonic=excluded.mnemonic, order_index=excluded.order_index, source=excluded.source, deleted=excluded.deleted, created_at=excluded.created_at, updated_at=excluded.updated_at;
INSERT INTO grammar_lesson (id, subject_id, grade, semester, category, title, summary, content_md, examples, common_mistakes, mnemonic, order_index, source, deleted, created_at, updated_at) VALUES (21, 2, 3, NULL, '词法·其他', '数词（基数词与序数词）', '数词分两种：基数词说数量，序数词说第几。', '## 这是啥
数词就是表示数字的词。

数词有两兄弟：
- **基数词**：说“有几个”。比如 one, two, three。
- **序数词**：说“第几个”。比如 first, second, third。

## 怎么用

### 1. 基数词：数数量
基数词就是 1, 2, 3…… 用来数东西。
- 例：I have **two** apples. 我有两个苹果。

### 2. 序数词：说第几
序数词就是第 1、第 2、第 3…… 前面通常加 **the**。
- 例：She is **the first** girl. 她是第一个女孩。

### 3. 序数词怎么变
- 1, 2, 3 要特殊记：one → first, two → second, three → third。
- 4 到 19：基数词后面加 **-th**。比如 four → fourth, six → sixth。
- 20 以上：十位不变，个位变序数词。比如 twenty-one → twenty-first。

### 4. 小提醒
- 序数词前常加 **the**。
- 说日期用序数词。比如 May **first**。
- 说名次用序数词。比如 **the second** place。', '[{"en": "I have three books.", "zh": "我有三本书。"}, {"en": "There are five birds.", "zh": "有五只鸟。"}, {"en": "He is the first boy.", "zh": "他是第一个男孩。"}, {"en": "Today is my fourth day.", "zh": "今天是我的第四天。"}, {"en": "She is the second girl.", "zh": "她是第二个女孩。"}, {"en": "It is May first.", "zh": "今天是五月一日。"}, {"en": "I am the third one.", "zh": "我是第三个。"}, {"en": "We have ten pencils.", "zh": "我们有十支铅笔。"}]', '["I have two book. 应说 I have two books. 数量超过一，名词要加 s。", "She is first girl. 应说 She is the first girl. 序数词前常加 the。", "Today is May one. 应说 Today is May first. 日期要用序数词。", "He is the three. 应说 He is the third. 说第几要用序数词。", "I am the fiveth. 应说 I am the fifth. five 变序数词是 fifth，不是 fiveth。"]', '基数词，数数量；序数词，说第几。一二三，特殊记；四后加 th 别忘记。', 20, 'ai', 0, '2026-09-18 17:34:16.226419', '2026-09-21 14:53:32.109975') ON CONFLICT(id) DO UPDATE SET subject_id=excluded.subject_id, grade=excluded.grade, semester=excluded.semester, category=excluded.category, title=excluded.title, summary=excluded.summary, content_md=excluded.content_md, examples=excluded.examples, common_mistakes=excluded.common_mistakes, mnemonic=excluded.mnemonic, order_index=excluded.order_index, source=excluded.source, deleted=excluded.deleted, created_at=excluded.created_at, updated_at=excluded.updated_at;
INSERT INTO grammar_lesson (id, subject_id, grade, semester, category, title, summary, content_md, examples, common_mistakes, mnemonic, order_index, source, deleted, created_at, updated_at) VALUES (22, 2, 4, NULL, '句法', '句子成分（主语/谓语/宾语）', '主语是“谁”，谓语是“做啥”，宾语是“对谁做”，句子三兄弟，排队不打架！', '## 这是啥
小朋友们，句子就像一个小家庭，有三个重要的成员：

- **主语**：句子里“谁”或者“什么”。比如：**I**、**You**、**Tom**、**The cat**。
- **谓语**：主语“做什么”或者“是什么”。比如：**eat**、**like**、**am**、**is**。
- **宾语**：谓语动作的“对象”，也就是“对谁做”。比如：**apples**、**English**、**me**。

记住：主语 + 谓语 + 宾语，就像“我 + 吃 + 苹果”。

## 怎么用
### 要点1：先找“谁”，那就是主语
句子开头常常是主语，表示谁在做事情。
- 例句：**I** like apples. （我喜欢苹果。）

### 要点2：再找“做什么”，那就是谓语
谓语是动词，告诉我们主语在干什么。
- 例句：She **reads** books. （她读书。）

### 要点3：最后找“对谁做”，那就是宾语
宾语通常在谓语后面，是动作的对象。
- 例句：He eats **rice**. （他吃米饭。）

### 要点4：主语 + 谓语 + 宾语，顺序不能乱
英语句子一般按这个顺序排队。
- 例句：**We** **play** **football**. （我们踢足球。）

## 小提醒
- 有时候句子只有主语和谓语，没有宾语。比如：**Birds** **fly**. （鸟飞。）
- 谓语是 am/is/are 时，后面跟的是“表语”，不是宾语。比如：I **am** **happy**. （我很开心。）', '[{"en": "I like apples.", "zh": "我喜欢苹果。"}, {"en": "She reads books.", "zh": "她读书。"}, {"en": "He eats rice.", "zh": "他吃米饭。"}, {"en": "We play football.", "zh": "我们踢足球。"}, {"en": "The cat drinks milk.", "zh": "猫喝牛奶。"}, {"en": "You sing songs.", "zh": "你唱歌。"}, {"en": "They watch TV.", "zh": "他们看电视。"}, {"en": "Birds fly.", "zh": "鸟飞。"}]', '["把宾语放在谓语前面，比如写成 I apples like.", "主语是 he/she/it 时，谓语忘记加 s，比如写成 He eat rice.", "把 am/is/are 后面的词当成宾语，比如把 I am happy. 说成 I am happy 的 happy 是宾语。", "句子没有主语，比如写成 Like apples.", "主语和谓语顺序颠倒，比如写成 Apples I like."]', '主语在前谁做事，谓语动词跟在后，宾语最后接动作，主谓宾顺序记心头！', 21, 'ai', 0, '2026-09-18 17:34:16.226419', '2026-09-21 14:53:48.179099') ON CONFLICT(id) DO UPDATE SET subject_id=excluded.subject_id, grade=excluded.grade, semester=excluded.semester, category=excluded.category, title=excluded.title, summary=excluded.summary, content_md=excluded.content_md, examples=excluded.examples, common_mistakes=excluded.common_mistakes, mnemonic=excluded.mnemonic, order_index=excluded.order_index, source=excluded.source, deleted=excluded.deleted, created_at=excluded.created_at, updated_at=excluded.updated_at;
INSERT INTO grammar_lesson (id, subject_id, grade, semester, category, title, summary, content_md, examples, common_mistakes, mnemonic, order_index, source, deleted, created_at, updated_at) VALUES (23, 2, 5, NULL, '句法', '英语五大基本句型', '英语句子五兄弟，主谓宾表补要牢记！', '## 这是啥
小朋友们，英语句子就像搭积木，有五种基本搭法，我们叫它们「五大基本句型」。

别怕，其实很简单！只要记住：谁（主语）+ 做什么（谓语）+ 其他。

## 怎么用
### 1. 主语 + 谓语（谁 + 做什么）
这种句子最短，谓语是不及物动词，后面不需要跟东西。
- 例句：Birds fly. 鸟儿飞。

### 2. 主语 + 谓语 + 宾语（谁 + 做什么 + 什么）
谓语是及物动词，后面要跟一个动作的承受者。
- 例句：I like apples. 我喜欢苹果。

### 3. 主语 + 谓语 + 表语（谁 + 是/变得 + 怎么样）
谓语是系动词（am, is, are, look, become 等），后面说明主语的身份或状态。
- 例句：She is happy. 她很开心。

### 4. 主语 + 谓语 + 双宾语（谁 + 给/送 + 谁 + 什么）
谓语后面跟两个宾语：一个是人（间接宾语），一个是物（直接宾语）。
- 例句：Dad gives me a gift. 爸爸给我一个礼物。

### 5. 主语 + 谓语 + 宾语 + 宾补（谁 + 让/叫 + 谁 + 做什么/怎么样）
宾语后面还要加一个词来补充说明宾语。
- 例句：We call him Tom. 我们叫他汤姆。

## 小提醒
- 先找主语和谓语，再看后面有没有宾语、表语等。
- 系动词后面跟的是表语，不是宾语哦！
- 双宾语可以改成「给谁」用 to/for 的结构。', '[{"en": "Birds fly.", "zh": "鸟儿飞。"}, {"en": "I like apples.", "zh": "我喜欢苹果。"}, {"en": "She is happy.", "zh": "她很开心。"}, {"en": "Dad gives me a gift.", "zh": "爸爸给我一个礼物。"}, {"en": "We call him Tom.", "zh": "我们叫他汤姆。"}, {"en": "The baby smiles.", "zh": "宝宝笑了。"}, {"en": "He looks tired.", "zh": "他看起来很累。"}, {"en": "Mom bought me a book.", "zh": "妈妈给我买了一本书。"}]', '["系动词后面错用宾语：She is happy. 不能说 She is happiness.", "双宾语顺序搞反：Dad gives a gift me. 应说 Dad gives me a gift.", "宾补前漏掉宾语：We call Tom. 应说 We call him Tom.", "不及物动词后面乱加宾语：I fly a kite. 可以，但 Birds fly the sky. 错，fly 这里不及物。", "把表语当宾语：He is a teacher. 不能说 He is teacher. 要加 a。"]', '主谓宾表补，五型记清楚；系动词后表，双宾人先物；宾补补宾语，句子不迷路！', 22, 'ai', 0, '2026-09-18 17:34:16.226419', '2026-09-21 14:54:00.942976') ON CONFLICT(id) DO UPDATE SET subject_id=excluded.subject_id, grade=excluded.grade, semester=excluded.semester, category=excluded.category, title=excluded.title, summary=excluded.summary, content_md=excluded.content_md, examples=excluded.examples, common_mistakes=excluded.common_mistakes, mnemonic=excluded.mnemonic, order_index=excluded.order_index, source=excluded.source, deleted=excluded.deleted, created_at=excluded.created_at, updated_at=excluded.updated_at;
INSERT INTO grammar_lesson (id, subject_id, grade, semester, category, title, summary, content_md, examples, common_mistakes, mnemonic, order_index, source, deleted, created_at, updated_at) VALUES (24, 2, 3, NULL, '句法', '一般疑问句（Do/Does/Is... 与回答）', '问句开头Do/Does/Is，回答就用Yes/No加主语和动词！', '## 这是啥

小朋友们，一般疑问句就是用来问「是还是不是」的句子。

比如你问：
- 你是学生吗？
- 你喜欢苹果吗？

回答只有两种：**Yes** 或者 **No**。

## 怎么用

### 要点1：有 am / is / are，就把它们提到最前面

句子里面有 **am / is / are** 的时候，把 **am / is / are** 放到句子开头，就变成问句啦！

- 原来：You **are** happy. 你很快乐。
- 问句：**Are** you happy? 你快乐吗？
- 回答：Yes, I am. / No, I''m not.

### 要点2：没有 am / is / are，就用 Do 或 Does 帮忙

句子里面没有 **am / is / are**，就用 **Do** 或 **Does** 开头。

- **I / you / we / they** 用 **Do**。
- **he / she / it** 用 **Does**。

例子：
- **Do** you like apples? 你喜欢苹果吗？
- **Does** she like apples? 她喜欢苹果吗？

### 要点3：回答要「前后一致」

问句用 **Do**，回答也用 **do**。
问句用 **Does**，回答也用 **does**。
问句用 **Is**，回答也用 **is**。

- Do you like apples? → Yes, I **do**. / No, I **don''t**.
- Does he like apples? → Yes, he **does**. / No, he **doesn''t**.
- Is she happy? → Yes, she **is**. / No, she **isn''t**.

### 要点4：Does 后面，动词要「脱掉 s」

用 **Does** 问的时候，后面的动词要变回原形，不能加 s。

- 对：Does he **like** apples?
- 错：Does he **likes** apples?

## 小练习

把下面的句子变成一般疑问句：
1. You are tall. → ______ you tall?
2. They like dogs. → ______ they like dogs?
3. She is my friend. → ______ she my friend?

答案：1. Are 2. Do 3. Is', '[{"en": "Are you happy? Yes, I am.", "zh": "你快乐吗？是的，我很快乐。"}, {"en": "Is she your teacher? No, she isn''t.", "zh": "她是你的老师吗？不，她不是。"}, {"en": "Do you like apples? Yes, I do.", "zh": "你喜欢苹果吗？是的，我喜欢。"}, {"en": "Does he like apples? No, he doesn''t.", "zh": "他喜欢苹果吗？不，他不喜欢。"}, {"en": "Do they play football? Yes, they do.", "zh": "他们踢足球吗？是的，他们踢。"}, {"en": "Does she like apples? Yes, she does.", "zh": "她喜欢苹果吗？是的，她喜欢。"}, {"en": "Are they students? No, they aren''t.", "zh": "他们是学生吗？不，他们不是。"}, {"en": "Does it have a tail? Yes, it does.", "zh": "它有尾巴吗？是的，它有。"}]', '["Do you like apples? 回答不能说 Yes, I like. 要说 Yes, I do.", "Does he likes apples? 错！Does 后面动词要脱掉 s，写成 Does he like apples?", "Are you happy? 回答不能说 Yes, I are. 要说 Yes, I am.", "Is she your teacher? 回答不能说 Yes, she does. 要说 Yes, she is.", "Do she like apples? 错！she 要用 Does，写成 Does she like apples?"]', '疑问句，不难记，am/is/are 提上去；没有它们别着急，Do 和 Does 来帮你；回答前后要一致，Yes/No 加主语！', 23, 'ai', 0, '2026-09-18 17:34:16.226419', '2026-09-21 14:53:40.824345') ON CONFLICT(id) DO UPDATE SET subject_id=excluded.subject_id, grade=excluded.grade, semester=excluded.semester, category=excluded.category, title=excluded.title, summary=excluded.summary, content_md=excluded.content_md, examples=excluded.examples, common_mistakes=excluded.common_mistakes, mnemonic=excluded.mnemonic, order_index=excluded.order_index, source=excluded.source, deleted=excluded.deleted, created_at=excluded.created_at, updated_at=excluded.updated_at;
INSERT INTO grammar_lesson (id, subject_id, grade, semester, category, title, summary, content_md, examples, common_mistakes, mnemonic, order_index, source, deleted, created_at, updated_at) VALUES (25, 2, 4, NULL, '句法', '特殊疑问句（what/where/when/who/how）', '疑问词开头，问啥答啥，句子倒着走！', '## 这是啥
特殊疑问句就是「问问题」的句子，开头用 **what / where / when / who / how** 这些「疑问小精灵」。

它们一出现，就表示：我要问一个具体的东西啦！

## 怎么用
### 1. 问「什么」用 what
问东西、名字、事情。
- 例句：**What** is your name?（你叫什么名字？）

### 2. 问「哪里」用 where
问地点、位置。
- 例句：**Where** is my book?（我的书在哪里？）

### 3. 问「什么时候」用 when
问时间、日子。
- 例句：**When** is your birthday?（你的生日是什么时候？）

### 4. 问「谁」用 who
问人。
- 例句：**Who** is that girl?（那个女孩是谁？）

### 5. 问「怎样」用 how
问方式、感觉、数量。
- 例句：**How** are you?（你好吗？）

## 小提醒
疑问词放最前面，后面跟着 be 动词或助动词，最后才是主语和动作。

比如：**What** + **is** + **this**?（这是什么？）

记住：疑问词打头阵，be 动词紧跟上，主语后面站，问号不能忘！', '[{"en": "What is your name?", "zh": "你叫什么名字？"}, {"en": "Where is my pencil?", "zh": "我的铅笔在哪里？"}, {"en": "When is your birthday?", "zh": "你的生日是什么时候？"}, {"en": "Who is your teacher?", "zh": "你的老师是谁？"}, {"en": "How are you?", "zh": "你好吗？"}, {"en": "What color is your bag?", "zh": "你的书包是什么颜色？"}, {"en": "Where are you from?", "zh": "你来自哪里？"}, {"en": "How old are you?", "zh": "你几岁了？"}]', '["What your name? 少了 is，应该是 What is your name?", "Where you are? 语序错了，应该是 Where are you?", "Who is she? 回答时不能说 She is my sister is. 要说 She is my sister.", "When is your birthday? 回答不能说 My birthday is on May. 要说 My birthday is in May.", "How are you? 回答不能说 I am fine, thank. 要说 I am fine, thank you."]', '疑问词，打头阵，be动词，紧跟上，主语后面站，问号不能忘！', 24, 'ai', 0, '2026-09-18 17:34:16.226419', '2026-09-21 14:53:51.724562') ON CONFLICT(id) DO UPDATE SET subject_id=excluded.subject_id, grade=excluded.grade, semester=excluded.semester, category=excluded.category, title=excluded.title, summary=excluded.summary, content_md=excluded.content_md, examples=excluded.examples, common_mistakes=excluded.common_mistakes, mnemonic=excluded.mnemonic, order_index=excluded.order_index, source=excluded.source, deleted=excluded.deleted, created_at=excluded.created_at, updated_at=excluded.updated_at;
INSERT INTO grammar_lesson (id, subject_id, grade, semester, category, title, summary, content_md, examples, common_mistakes, mnemonic, order_index, source, deleted, created_at, updated_at) VALUES (26, 2, 3, NULL, '句法', '祈使句', '祈使句，就是命令、请求或建议，动词开头，主语（你）藏起来！', '## 这是啥

小朋友，你有没有听过老师说：

- **Stand up!**（起立！）
- **Open your book.**（打开书。）

这些句子，动词在最前面，没有“你”字，但大家都知道是让“你”做事情。

这就是**祈使句**！

祈使句就是：**叫别人做事情，或者请别人做事情**。

## 怎么用

### 1. 动词开头，主语“你”藏起来

说祈使句时，第一个词就是**动词**。

“你”不用说出来，因为大家都知道是“你”。

- **Sit down.**（坐下。）
- **Come here.**（过来。）

### 2. 请别人做事，句首加 please 更礼貌

想让说话更客气，就在句子开头或结尾加 **please**。

- **Please stand up.**（请起立。）
- **Sit down, please.**（请坐下。）

### 3. 叫别人不要做，动词前加 Don''t

不想让别人做某件事，就在动词前加 **Don''t**。

- **Don''t run.**（不要跑。）
- **Don''t talk.**（不要说话。）

### 4. 句末用句号或感叹号

祈使句说完，可以用**句号**，也可以用**感叹号**。

- **Close the door.**（关上门。）
- **Hurry up!**（快点！）

## 小提醒

祈使句里，**没有 am, is, are**，直接说动词就可以啦！', '[{"en": "Stand up!", "zh": "起立！"}, {"en": "Sit down, please.", "zh": "请坐下。"}, {"en": "Open your book.", "zh": "打开你的书。"}, {"en": "Please come here.", "zh": "请过来这里。"}, {"en": "Don''t run.", "zh": "不要跑。"}, {"en": "Don''t talk in class.", "zh": "不要在课堂上说话。"}, {"en": "Close the door, please.", "zh": "请关上门。"}, {"en": "Hurry up!", "zh": "快点！"}]', '["祈使句里加主语：不能说 You stand up.，要说 Stand up.", "Don''t 后面加 to：不能说 Don''t to run.，要说 Don''t run.", "please 位置放错：不能说 Please you sit down.，要说 Please sit down. 或 Sit down, please.", "祈使句里用 am/is/are：不能说 You are sit down.，要说 Sit down.", "否定句忘记加 Don''t：不能说 Run not.，要说 Don''t run."]', '祈使句，动词开头，主语你，藏起来；请人做事加 please，叫人别做 Don''t 来！', 25, 'ai', 0, '2026-09-18 17:34:16.226419', '2026-09-21 14:53:44.275959') ON CONFLICT(id) DO UPDATE SET subject_id=excluded.subject_id, grade=excluded.grade, semester=excluded.semester, category=excluded.category, title=excluded.title, summary=excluded.summary, content_md=excluded.content_md, examples=excluded.examples, common_mistakes=excluded.common_mistakes, mnemonic=excluded.mnemonic, order_index=excluded.order_index, source=excluded.source, deleted=excluded.deleted, created_at=excluded.created_at, updated_at=excluded.updated_at;
INSERT INTO grammar_lesson (id, subject_id, grade, semester, category, title, summary, content_md, examples, common_mistakes, mnemonic, order_index, source, deleted, created_at, updated_at) VALUES (27, 2, 4, NULL, '句法', 'there be 句型', '有某物，there be 来帮忙，单数 is 复数 are，就近原则记心上！', '## 这是啥

小朋友们，如果老师让你说「桌子上有一本书」，你会怎么说？

中文用「有」，英语里可不能用 have 哦！

我们要请出今天的主角——**there be 句型**！

它的意思就是：**某地有某物**。

比如：
- There is a cat on the bed. 床上有一只猫。
- There are two apples in the bag. 袋子里有两个苹果。

记住：there be 就像一个小导游，带我们看「哪里有什么」。

## 怎么用

### 要点1：单数用 is，复数用 are

看后面的东西，一个用 **is**，两个或更多用 **are**。

- There **is** a book on the desk. 桌上有一本书。
- There **are** three pens in the box. 盒子里有三支笔。

### 要点2：否定句，be 后加 not

想说「没有」，就在 is/are 后面加 **not**。

- There **is not** a dog in the park. 公园里没有狗。
- There **are not** any birds in the tree. 树上没有鸟。

### 要点3：疑问句，be 提到 there 前

想问「有……吗？」，就把 is/are 放到最前面。

- **Is** there a library near here? 这附近有图书馆吗？
- **Are** there any flowers in the garden? 花园里有花吗？

### 要点4：就近原则

如果有多个东西，be 动词跟**最近的那个**保持一致。

- There **is** a pen and two books on the desk. 桌上有一支笔和两本书。（离 be 最近的是 a pen，单数，用 is）
- There **are** two books and a pen on the desk. 桌上有两本书和一支笔。（离 be 最近的是 two books，复数，用 are）

## 小提醒

- there be 表示「有」，但和 have 不一样哦！have 表示「某人拥有」。
- 比如：I have a book. 我有一本书。（书是我的）
- There is a book on the desk. 桌上有一本书。（书不一定是我 的）', '[{"en": "There is a bird in the tree.", "zh": "树上有一只鸟。"}, {"en": "There are many students in the classroom.", "zh": "教室里有很多学生。"}, {"en": "There is not a cat under the chair.", "zh": "椅子下面没有猫。"}, {"en": "Are there any apples on the table?", "zh": "桌子上有苹果吗？"}, {"en": "There is a pencil and two rulers in the pencil box.", "zh": "铅笔盒里有一支铅笔和两把尺子。"}, {"en": "There are two rulers and a pencil in the pencil box.", "zh": "铅笔盒里有两把尺子和一支铅笔。"}, {"en": "Is there a park near your home?", "zh": "你家附近有公园吗？"}]', '["There is two books on the desk. （错！two books 是复数，要用 There are）", "There have a cat in the room. （错！there be 不能和 have 一起用，要说 There is a cat）", "Is there any water in the cup? 回答 Yes, there is. 不能说 Yes, it is.", "There are a pen and a book on the desk. （错！就近原则，a pen 是单数，要用 There is）", "Are there some birds in the tree? （错！疑问句里 some 要变成 any）"]', '有某物，there be，单数 is 复数 are；否定 not 加后头，疑问 be 提前头；多个东西看最近，就近原则记心头！', 26, 'ai', 0, '2026-09-18 17:34:16.226419', '2026-09-21 14:53:56.986831') ON CONFLICT(id) DO UPDATE SET subject_id=excluded.subject_id, grade=excluded.grade, semester=excluded.semester, category=excluded.category, title=excluded.title, summary=excluded.summary, content_md=excluded.content_md, examples=excluded.examples, common_mistakes=excluded.common_mistakes, mnemonic=excluded.mnemonic, order_index=excluded.order_index, source=excluded.source, deleted=excluded.deleted, created_at=excluded.created_at, updated_at=excluded.updated_at;
INSERT INTO grammar_lesson (id, subject_id, grade, semester, category, title, summary, content_md, examples, common_mistakes, mnemonic, order_index, source, deleted, created_at, updated_at) VALUES (28, 2, 6, NULL, '句法', '感叹句入门（What / How）', '感叹句，真简单：What 后面跟名词，How 后面跟形容词或副词！', '## 这是啥
感叹句就是用来表达「哇！好厉害！」「真漂亮！」这种强烈感情的句子。

比如你看到一只超大的狗，你会说：
- **What a big dog!**（好大的一只狗啊！）
- **How big the dog is!**（这只狗好大啊！）

英语里最常用的两个感叹词就是 **What** 和 **How**。

## 怎么用

### 要点 1：What 后面跟名词
**规则**：What + 名词（短语）+ 主语 + 谓语！

**例句**：
- What a cute cat!（好可爱的一只猫！）
- What nice weather!（多好的天气啊！）

> 小提醒：如果名词是可数名词单数，前面要加 **a** 或 **an**。

### 要点 2：How 后面跟形容词或副词
**规则**：How + 形容词/副词 + 主语 + 谓语！

**例句**：
- How tall he is!（他好高啊！）
- How fast she runs!（她跑得真快！）

### 要点 3：What 和 How 可以互换
**规则**：同一个意思，可以用 What 说，也可以用 How 说。

**例句**：
- What a beautiful flower! = How beautiful the flower is!（多美的一朵花啊！）

### 要点 4：口语里常省略主语和谓语
**规则**：说话时，后面的「主语 + 谓语」常常不说。

**例句**：
- What a mess!（好乱啊！）
- How nice!（真棒！）

## 小练习
看到下面这些句子，你能判断用 What 还是 How 吗？
- ___ a smart boy!（What）
- ___ clever the boy is!（How）
- ___ delicious the cake is!（How）
- ___ big apples!（What）', '[{"en": "What a big dog!", "zh": "好大的一只狗啊！"}, {"en": "What nice weather!", "zh": "多好的天气啊！"}, {"en": "How tall he is!", "zh": "他好高啊！"}, {"en": "How fast she runs!", "zh": "她跑得真快！"}, {"en": "What a beautiful flower!", "zh": "多美的一朵花啊！"}, {"en": "How beautiful the flower is!", "zh": "这朵花多美啊！"}, {"en": "What a mess!", "zh": "好乱啊！"}, {"en": "How nice!", "zh": "真棒！"}]', '["What 后面直接跟形容词，比如不能说 What beautiful!，要说 What a beautiful flower! 或 How beautiful!", "How 后面直接跟名词，比如不能说 How a big dog!，要说 What a big dog! 或 How big the dog is!", "可数名词单数前忘记加 a/an，比如不能说 What big dog!，要说 What a big dog!", "把 What 和 How 的顺序搞反，比如不能说 How a nice day!，要说 What a nice day!", "在感叹句里用陈述语序，比如不能说 What a big dog it is! 虽然语法对，但口语里常省略 it is，直接说 What a big dog! 更自然。"]', 'What 跟名词，How 跟形副；
感叹语气强，主语谓语可省去！', 27, 'ai', 0, '2026-09-18 17:34:16.226419', '2026-09-21 14:54:05.188575') ON CONFLICT(id) DO UPDATE SET subject_id=excluded.subject_id, grade=excluded.grade, semester=excluded.semester, category=excluded.category, title=excluded.title, summary=excluded.summary, content_md=excluded.content_md, examples=excluded.examples, common_mistakes=excluded.common_mistakes, mnemonic=excluded.mnemonic, order_index=excluded.order_index, source=excluded.source, deleted=excluded.deleted, created_at=excluded.created_at, updated_at=excluded.updated_at;
INSERT INTO grammar_lesson (id, subject_id, grade, semester, category, title, summary, content_md, examples, common_mistakes, mnemonic, order_index, source, deleted, created_at, updated_at) VALUES (29, 2, 6, NULL, '句法', '并列句入门（and/but/or 连接）', '两个小句子，手拉手做朋友：and 加一加，but 转个弯，or 选一选。', '## 这是啥

小朋友，你说话的时候，是不是经常把两件小事连在一起说？

比如：

- 我喜欢苹果。我喜欢香蕉。
- 我喜欢苹果 **and** 香蕉。

这个 **and** 就像一座小桥，把两个句子连成一个大句子。

这种用 **and / but / or** 连起来的句子，就叫 **并列句**。

> 简单说：两个小句子 + 一个连接词 = 一个并列句。

## 怎么用

### 要点 1：and 表示「加一加」

**规则：** 两件事差不多、一起发生，就用 **and**。

**例句：** I like apples **and** I like bananas.  
（我喜欢苹果，我也喜欢香蕉。）

### 要点 2：but 表示「转个弯」

**规则：** 前面说一件事，后面说不一样的事，就用 **but**。

**例句：** I am small **but** I am strong.  
（我个子小，但是我很强壮。）

### 要点 3：or 表示「选一选」

**规则：** 两件事只能选一个，就用 **or**。

**例句：** Do you like tea **or** juice?  
（你喜欢茶还是果汁？）

### 要点 4：连接词放中间，句子两边要完整

**规则：** **and / but / or** 放在两个小句子中间，两边都要有主语和动词。

**例句：** She sings **and** he dances.  
（她唱歌，他跳舞。）

## 小提醒

- 两个小句子要差不多重要，不能一个太长一个太短。
- 连接词前面可以加逗号，也可以不加。
- 说的时候，**but** 前面要停一下，**or** 最后要升调。', '[{"en": "I like apples and I like bananas.", "zh": "我喜欢苹果，我也喜欢香蕉。"}, {"en": "I am small but I am strong.", "zh": "我个子小，但是我很强壮。"}, {"en": "Do you like tea or juice?", "zh": "你喜欢茶还是果汁？"}, {"en": "She sings and he dances.", "zh": "她唱歌，他跳舞。"}, {"en": "It is cold but I am happy.", "zh": "天气冷，但是我很开心。"}, {"en": "We can play football or we can play basketball.", "zh": "我们可以踢足球，或者打篮球。"}, {"en": "My mom cooks and my dad cleans.", "zh": "我妈妈做饭，我爸爸打扫。"}]', '["I like apples and bananas. 不能写成 I like apples and I like bananas and.", "but 不能写成 and，意思不一样：I am small but I am strong. 不是 I am small and I am strong.", "or 不能写成 and：Do you like tea or juice? 不是 Do you like tea and juice?", "连接词两边要完整：She sings and dances. 可以，但 She sings and he. 不行。", "and 不能连三个以上小句子不休息：I like A and B and C and D. 最好说 I like A, B, C and D."]', 'and 加一加，but 转个弯，or 选一选，小桥连句真简单！', 28, 'ai', 0, '2026-09-18 17:34:16.226419', '2026-09-21 14:54:09.524739') ON CONFLICT(id) DO UPDATE SET subject_id=excluded.subject_id, grade=excluded.grade, semester=excluded.semester, category=excluded.category, title=excluded.title, summary=excluded.summary, content_md=excluded.content_md, examples=excluded.examples, common_mistakes=excluded.common_mistakes, mnemonic=excluded.mnemonic, order_index=excluded.order_index, source=excluded.source, deleted=excluded.deleted, created_at=excluded.created_at, updated_at=excluded.updated_at;
INSERT INTO grammar_lesson (id, subject_id, grade, semester, category, title, summary, content_md, examples, common_mistakes, mnemonic, order_index, source, deleted, created_at, updated_at) VALUES (30, 2, 3, NULL, '词法·介词', 'in 表示上午/下午/晚上', '上午下午和晚上，前面都用 in 来帮忙！', '## 这是啥
小朋友，你每天是不是会说「早上好」「下午好」「晚上好」呀？
英语里，说「在上午」「在下午」「在晚上」，前面都要加一个小词——**in**。
记住：**in the morning, in the afternoon, in the evening**。

## 怎么用
### 1. 在上午，用 in the morning
早上 6 点到 12 点，就是 morning。
- 例句：I read books **in the morning**. （我在上午读书。）

### 2. 在下午，用 in the afternoon
中午 12 点到傍晚 6 点，就是 afternoon。
- 例句：We play football **in the afternoon**. （我们在下午踢足球。）

### 3. 在晚上，用 in the evening
傍晚 6 点到睡觉前，就是 evening。
- 例句：My mom cooks dinner **in the evening**. （我妈妈在晚上做晚饭。）

### 4. 小提醒：in 后面要加 the
说这三个时间时，in 和 morning/afternoon/evening 中间，别忘了 **the** 哦！
- 对：in **the** morning
- 错：in morning

## 小练习
想一想，下面该填什么？
1. I eat breakfast ___ the morning. （答案：in）
2. She does homework ___ the evening. （答案：in）
3. They play games ___ the afternoon. （答案：in）', '[{"en": "I get up at 7 in the morning.", "zh": "我在早上7点起床。"}, {"en": "We have English class in the morning.", "zh": "我们在上午有英语课。"}, {"en": "He plays basketball in the afternoon.", "zh": "他在下午打篮球。"}, {"en": "My sister draws pictures in the afternoon.", "zh": "我妹妹在下午画画。"}, {"en": "We watch TV in the evening.", "zh": "我们在晚上看电视。"}, {"en": "My dad reads newspapers in the evening.", "zh": "我爸爸在晚上看报纸。"}, {"en": "I do my homework in the evening.", "zh": "我在晚上做作业。"}]', '["in morning 少了 the，应该是 in the morning", "in the morning 写成 on the morning，上午下午晚上都用 in", "in the afternoon 写成 in afternoon，忘了加 the", "把 in the evening 说成 in the night，晚上一般说 in the evening 或 at night", "in the morning 和 at morning 搞混，上午用 in，不用 at"]', '上午下午和晚上，in the 开头不能忘！', 0, 'manual', 0, '2026-09-18 18:02:50.307030', '2026-09-18 18:02:55.617397') ON CONFLICT(id) DO UPDATE SET subject_id=excluded.subject_id, grade=excluded.grade, semester=excluded.semester, category=excluded.category, title=excluded.title, summary=excluded.summary, content_md=excluded.content_md, examples=excluded.examples, common_mistakes=excluded.common_mistakes, mnemonic=excluded.mnemonic, order_index=excluded.order_index, source=excluded.source, deleted=excluded.deleted, created_at=excluded.created_at, updated_at=excluded.updated_at;
INSERT INTO grammar_lesson (id, subject_id, grade, semester, category, title, summary, content_md, examples, common_mistakes, mnemonic, order_index, source, deleted, created_at, updated_at) VALUES (31, 2, 3, NULL, '词法·介词', 'on 表示星期几', '星期几前加 on，就像给日子穿件小衣裳！', '## 这是啥
小朋友们，你们知道吗？英语里说到「星期几」的时候，前面要加一个小词——**on**。

就像我们出门要穿鞋子一样，星期几出门也要穿上 **on** 这双小鞋子哦！

## 怎么用
### 要点 1：星期几前面，一定要加 on
说「在星期一」「在星期二」的时候，星期几前面要放 **on**。

- 例句：**On Monday**, I go to school. （在星期一，我去上学。）

### 要点 2：on 后面直接跟星期几，不用再加别的词
on 后面直接写 Monday、Tuesday 这些词，不要加 the 或 a。

- 例句：We have music **on Wednesday**. （我们在星期三有音乐课。）

### 要点 3：星期几的首字母要大写
Monday、Tuesday、Sunday 这些词，第一个字母永远是大写，像小朋友的名字一样。

- 例句：**On Sunday**, I play with my dog. （在星期天，我和我的狗玩。）

### 要点 4：on 也可以放在句子中间或开头
on + 星期几可以放在句首，也可以放在句尾，意思都一样。

- 例句：I read books **on Friday**. （我在星期五看书。）
- 例句：**On Saturday**, we go to the park. （在星期六，我们去公园。）', '[{"en": "On Monday, I go to school.", "zh": "在星期一，我去上学。"}, {"en": "We have music on Wednesday.", "zh": "我们在星期三有音乐课。"}, {"en": "On Sunday, I play with my dog.", "zh": "在星期天，我和我的狗玩。"}, {"en": "I read books on Friday.", "zh": "我在星期五看书。"}, {"en": "On Saturday, we go to the park.", "zh": "在星期六，我们去公园。"}, {"en": "She has a dance class on Tuesday.", "zh": "她在星期二有舞蹈课。"}, {"en": "On Thursday, we eat noodles.", "zh": "在星期四，我们吃面条。"}]', '["I go to school in Monday. （错！星期几前面要用 on，不是 in）", "On monday, I play football. （错！Monday 的首字母 M 要大写）", "I go to school on the Monday. （错！on 后面直接跟 Monday，不加 the）", "We have English at Friday. （错！星期几前面不用 at，要用 on）", "On Sunday I play. （对，但最好写成 On Sunday, I play. 加个逗号更清楚）"]', '星期几，穿 on 鞋，首字母，大写写！', 0, 'manual', 0, '2026-09-18 18:02:50.446030', '2026-09-18 18:02:59.385366') ON CONFLICT(id) DO UPDATE SET subject_id=excluded.subject_id, grade=excluded.grade, semester=excluded.semester, category=excluded.category, title=excluded.title, summary=excluded.summary, content_md=excluded.content_md, examples=excluded.examples, common_mistakes=excluded.common_mistakes, mnemonic=excluded.mnemonic, order_index=excluded.order_index, source=excluded.source, deleted=excluded.deleted, created_at=excluded.created_at, updated_at=excluded.updated_at;
INSERT INTO grammar_lesson (id, subject_id, grade, semester, category, title, summary, content_md, examples, common_mistakes, mnemonic, order_index, source, deleted, created_at, updated_at) VALUES (32, 2, 3, NULL, '词法·介词', 'at 表示具体时刻', '几点几分用 at，就像闹钟叮叮叮！', '## 这是啥

小朋友，你想告诉别人「我几点做什么」吗？

比如：我 **7 点** 起床。

这个「7 点」就是**具体时刻**。

英语里，**具体时刻前面要加 at**。

记住：**at + 几点几分**。

## 怎么用

### 1. at 后面直接跟「几点」

规则：at 后面写时间点，比如 6:00、7:30。

例句：I get up **at** 7:00. 我 7 点起床。

### 2. at 也可以跟「中午、晚上」这些词

规则：at noon（中午）、at night（晚上）也要用 at。

例句：I eat lunch **at** noon. 我中午吃午饭。

### 3. at 要放在时间前面

规则：先说事情，再说 at + 时间。

例句：We go to school **at** 8:00. 我们 8 点去上学。

### 4. 问时间用 What time

规则：问「几点」用 What time，回答用 at。

例句：What time is it? It''s **at** 9:00. 几点了？9 点。

## 小提醒

- at 是「点」，不是「段」。
- 只说「几点几分」，就用 at。
- 不要忘记 at 哦！', '[{"en": "I get up at 7:00.", "zh": "我 7 点起床。"}, {"en": "She goes to school at 8:00.", "zh": "她 8 点去上学。"}, {"en": "We have lunch at noon.", "zh": "我们中午吃午饭。"}, {"en": "He plays football at 4:30.", "zh": "他 4 点半踢足球。"}, {"en": "I go to bed at 9:00.", "zh": "我 9 点睡觉。"}, {"en": "They watch TV at night.", "zh": "他们晚上看电视。"}, {"en": "What time do you eat dinner? At 6:00.", "zh": "你几点吃晚饭？6 点。"}]', '["I get up 7:00. 漏掉了 at，应该是 I get up at 7:00.", "I get up in 7:00. 不能用 in，具体时刻要用 at。", "I get up on 7:00. 不能用 on，on 用于具体某一天。", "At 7:00 I get up. 虽然可以，但小学生更常用 I get up at 7:00.", "What time is it? 回答时忘记 at，比如 It''s 9:00. 可以，但说「在 9 点」要用 at 9:00。"]', '具体时刻用 at，几点几分别忘记；中午晚上也用它，闹钟一响 at 来啦！', 0, 'manual', 0, '2026-09-18 18:02:50.570031', '2026-09-18 18:03:03.022439') ON CONFLICT(id) DO UPDATE SET subject_id=excluded.subject_id, grade=excluded.grade, semester=excluded.semester, category=excluded.category, title=excluded.title, summary=excluded.summary, content_md=excluded.content_md, examples=excluded.examples, common_mistakes=excluded.common_mistakes, mnemonic=excluded.mnemonic, order_index=excluded.order_index, source=excluded.source, deleted=excluded.deleted, created_at=excluded.created_at, updated_at=excluded.updated_at;
INSERT INTO grammar_lesson (id, subject_id, grade, semester, category, title, summary, content_md, examples, common_mistakes, mnemonic, order_index, source, deleted, created_at, updated_at) VALUES (33, 2, 4, NULL, '词法·介词', 'in 表示月份', '月份前面用 in，就像把月份装进小盒子里！', '## 这是啥

小朋友，你想说“在几月”的时候，英语要用 **in** 这个单词。

比如：**in May** 就是“在五月”。

**in** 就像一个小盒子，把月份装进去啦！

## 怎么用

### 要点1：月份前面直接加 in

规则：说“在几月”，就在月份前面放 **in**。

例句：**I go to school in September.**（我九月去上学。）

### 要点2：in 后面跟月份，不用加 the

规则：**in** 后面直接跟月份单词，不要加 **the**。

例句：**My birthday is in June.**（我的生日在六月。）

### 要点3：一年有12个月，每个都能用 in

规则：January, February, March... 所有月份前面都可以用 **in**。

例句：**It is cold in January.**（一月很冷。）

### 要点4：问“在几月”也用 in

规则：问别人“在几月”时，句子开头用 **In which month...?** 或者 **When...?** 回答时用 **in + 月份**。

例句：**— When is your birthday? — It is in October.**（—你的生日在什么时候？—在十月。）', '[{"en": "I go to school in September.", "zh": "我九月去上学。"}, {"en": "My birthday is in June.", "zh": "我的生日在六月。"}, {"en": "It is cold in January.", "zh": "一月很冷。"}, {"en": "We have a party in December.", "zh": "我们在十二月有一个派对。"}, {"en": "She visits her grandma in May.", "zh": "她在五月去看望她的奶奶。"}, {"en": "The flowers bloom in April.", "zh": "花儿在四月开放。"}, {"en": "— When is your birthday? — It is in October.", "zh": "—你的生日在什么时候？—在十月。"}, {"en": "We go swimming in July.", "zh": "我们在七月去游泳。"}]', '["I go to school on September. 错啦！月份前面要用 in，不是 on。", "My birthday is in the June. 错啦！in 后面直接跟月份，不要加 the。", "I go to school in September month. 错啦！September 本身就是月份，不用再加 month。", "My birthday is at June. 错啦！月份前面要用 in，不是 at。", "I go to school in september. 错啦！月份单词首字母要大写，September 才对。"]', '月份前面要用 in，就像盒子装星星；不用 on 不用 at，大写字母要记清！', 0, 'manual', 0, '2026-09-18 18:02:50.695030', '2026-09-18 18:03:06.656904') ON CONFLICT(id) DO UPDATE SET subject_id=excluded.subject_id, grade=excluded.grade, semester=excluded.semester, category=excluded.category, title=excluded.title, summary=excluded.summary, content_md=excluded.content_md, examples=excluded.examples, common_mistakes=excluded.common_mistakes, mnemonic=excluded.mnemonic, order_index=excluded.order_index, source=excluded.source, deleted=excluded.deleted, created_at=excluded.created_at, updated_at=excluded.updated_at;
INSERT INTO grammar_lesson (id, subject_id, grade, semester, category, title, summary, content_md, examples, common_mistakes, mnemonic, order_index, source, deleted, created_at, updated_at) VALUES (34, 2, 4, NULL, '词法·介词', 'in 表示季节', '季节前面加 in，春夏秋冬都搞定！', '## 这是啥
小朋友们，一年有四个季节：春天、夏天、秋天、冬天。
当我们要说「在春天」「在夏天」的时候，英语里要在季节前面加一个小词——**in**。
就像给季节戴上一顶小帽子，**in** 就是那顶帽子！

## 怎么用
### 要点1：季节前面直接加 in
规则：in + 季节，表示「在……季节」。
例句：I fly kites **in spring**. （我在春天放风筝。）

### 要点2：四个季节都能用
规则：spring, summer, autumn/fall, winter 前面都可以加 in。
例句：We swim **in summer**. （我们在夏天游泳。）

### 要点3：in 后面不加 the
规则：说「在春天」时，直接说 in spring，不说 in the spring（口语里有时可以，但小学阶段先记住不加 the 更简单）。
例句：It snows **in winter**. （冬天会下雪。）

### 要点4：in 还可以表示在某个季节做某事
规则：in + 季节 + 其他动作，说明这个季节里发生的事。
例句：Leaves turn yellow **in autumn**. （秋天树叶变黄。）

## 小提醒
- in 是「在……里」，季节是一个大盒子，我们就在盒子里。
- 记住：季节前面，in 来帮忙！', '[{"en": "I fly kites in spring.", "zh": "我在春天放风筝。"}, {"en": "We go swimming in summer.", "zh": "我们在夏天去游泳。"}, {"en": "Leaves turn yellow in autumn.", "zh": "秋天树叶变黄。"}, {"en": "It snows in winter.", "zh": "冬天会下雪。"}, {"en": "Birds sing in spring.", "zh": "鸟儿在春天唱歌。"}, {"en": "We eat ice cream in summer.", "zh": "我们在夏天吃冰淇淋。"}, {"en": "We pick apples in autumn.", "zh": "我们在秋天摘苹果。"}, {"en": "We make snowmen in winter.", "zh": "我们在冬天堆雪人。"}]', '["I fly kites on spring. （错：季节前用 in，不用 on）", "We swim in the summer. （小学阶段先记：季节前不加 the，直接 in summer）", "It snows at winter. （错：季节前不用 at，要用 in）", "I go to school in Monday. （错：星期前用 on，季节前才用 in）", "We play in summer. 写成 We play on summer. （错：季节前用 in）"]', '季节前面加 in，春夏秋冬记在心！', 0, 'manual', 0, '2026-09-18 18:02:50.893033', '2026-09-18 18:03:10.244909') ON CONFLICT(id) DO UPDATE SET subject_id=excluded.subject_id, grade=excluded.grade, semester=excluded.semester, category=excluded.category, title=excluded.title, summary=excluded.summary, content_md=excluded.content_md, examples=excluded.examples, common_mistakes=excluded.common_mistakes, mnemonic=excluded.mnemonic, order_index=excluded.order_index, source=excluded.source, deleted=excluded.deleted, created_at=excluded.created_at, updated_at=excluded.updated_at;
INSERT INTO grammar_lesson (id, subject_id, grade, semester, category, title, summary, content_md, examples, common_mistakes, mnemonic, order_index, source, deleted, created_at, updated_at) VALUES (35, 2, 4, NULL, '词法·介词', 'in 表示年份', '年份前面加 in，就像时间穿外衣！', '## 这是啥

小朋友，当你想说“在某一年”的时候，只要在年份前面加上一个小词 **in** 就可以啦！

比如：**in 2020** 就是“在2020年”。

## 怎么用

### 1. 年份前面直接加 in

规则：**in + 年份**，表示“在某一年”。

例句：I was born **in 2015**.
（我出生在2015年。）

### 2. 年份读法有规律

规则：年份通常分成两个数字来读，比如 2020 读作 twenty twenty。

例句：We will go to Beijing **in 2024**.
（我们将在2024年去北京。）

### 3. 问“哪一年”用 What year

规则：问在哪一年，用 **What year** 开头，回答用 **in + 年份**。

例句：— What year are you in Grade 4?
— I am in Grade 4 **in 2025**.
（—你四年级是哪一年？—我2025年上四年级。）

### 4. 年份前不用 on 或 at

规则：记住，年份前面只用 **in**，不用 on 或 at。

例句：My sister will start school **in 2026**.
（我妹妹将在2026年开始上学。）

## 小提醒

- 年份前面永远用 **in**。
- 读年份时，先读前两个数字，再读后两个数字。
- 说“在某一年”就用 **in + 年份**。', '[{"en": "I was born in 2015.", "zh": "我出生在2015年。"}, {"en": "We will go to Beijing in 2024.", "zh": "我们将在2024年去北京。"}, {"en": "My sister will start school in 2026.", "zh": "我妹妹将在2026年开始上学。"}, {"en": "What year did you go to Shanghai? I went there in 2022.", "zh": "你哪一年去的上海？我2022年去的。"}, {"en": "The Olympic Games were held in 2021.", "zh": "奥运会在2021年举办。"}, {"en": "I will be ten years old in 2027.", "zh": "我将在2027年十岁。"}, {"en": "My parents got married in 2010.", "zh": "我父母在2010年结婚。"}]', '["I was born on 2015. (年份前不能用 on，要用 in)", "I was born at 2015. (年份前不能用 at，要用 in)", "I born in 2015. (缺少 was，应该是 I was born)", "I am born in 2015. (表示出生用 was born，不是 am born)", "in 2020 year (年份后面不加 year，直接说 in 2020)"]', '年份前面加 in，就像时间穿外衣；on 和 at 靠边站，in 是年份好伙伴！', 0, 'manual', 0, '2026-09-18 18:02:51.049282', '2026-09-18 18:03:13.995174') ON CONFLICT(id) DO UPDATE SET subject_id=excluded.subject_id, grade=excluded.grade, semester=excluded.semester, category=excluded.category, title=excluded.title, summary=excluded.summary, content_md=excluded.content_md, examples=excluded.examples, common_mistakes=excluded.common_mistakes, mnemonic=excluded.mnemonic, order_index=excluded.order_index, source=excluded.source, deleted=excluded.deleted, created_at=excluded.created_at, updated_at=excluded.updated_at;
INSERT INTO grammar_lesson (id, subject_id, grade, semester, category, title, summary, content_md, examples, common_mistakes, mnemonic, order_index, source, deleted, created_at, updated_at) VALUES (36, 2, 4, NULL, '词法·介词', 'on 表示具体日期', '具体某一天，前面就用 on，日子一出现，on 来站岗！', '## 这是啥
小朋友们，当我们要说「在具体哪一天」的时候，就要请出小帮手 **on** 啦！

比如：在星期一、在 6 月 1 日、在我生日那天，都要用 **on**。

## 怎么用
### 要点 1：on + 星期几
说「在星期几」的时候，星期前面加 **on**。
- 例句：**On Monday**, I play football. 在星期一，我踢足球。

### 要点 2：on + 几月几日
说「在几月几号」的时候，日期前面加 **on**。
- 例句：**On June 1st**, we have a party. 在 6 月 1 日，我们开派对。

### 要点 3：on + 具体某天的早上/下午/晚上
如果早上、下午、晚上是「具体某一天」的，也用 **on**。
- 例句：**On Sunday morning**, I read books. 在星期天早上，我看书。

### 要点 4：on + 节日当天
说「在节日那一天」，也用 **on**。
- 例句：**On Children''s Day**, I am very happy. 在儿童节，我很开心。

## 小提醒
- **on** 后面跟的是「具体的一天」，不是月份，也不是年份哦！
- 月份前面用 **in**，年份前面也用 **in**。
- 具体到某一天，就换成 **on**。', '[{"en": "On Monday, I go to school.", "zh": "在星期一，我去上学。"}, {"en": "On June 1st, we have a party.", "zh": "在 6 月 1 日，我们开派对。"}, {"en": "On Sunday morning, I read books.", "zh": "在星期天早上，我看书。"}, {"en": "On Children''s Day, I am very happy.", "zh": "在儿童节，我很开心。"}, {"en": "My birthday is on May 5th.", "zh": "我的生日在 5 月 5 日。"}, {"en": "We have a music class on Friday.", "zh": "我们在星期五有一节音乐课。"}, {"en": "On Saturday afternoon, I play with my friends.", "zh": "在星期六下午，我和朋友们玩。"}]', '["I go to school in Monday. 应改成 I go to school on Monday.", "My birthday is in May 5th. 应改成 My birthday is on May 5th.", "We have a party on June. 应改成 We have a party in June.", "On Sunday morning 不能写成 In Sunday morning。", "On Children''s Day 不能写成 In Children''s Day。"]', '具体某天用 on 站，星期日期节日全；月份年份 in 来管，on 和 in 别弄乱！', 0, 'manual', 0, '2026-09-18 18:02:51.196285', '2026-09-18 18:03:17.500168') ON CONFLICT(id) DO UPDATE SET subject_id=excluded.subject_id, grade=excluded.grade, semester=excluded.semester, category=excluded.category, title=excluded.title, summary=excluded.summary, content_md=excluded.content_md, examples=excluded.examples, common_mistakes=excluded.common_mistakes, mnemonic=excluded.mnemonic, order_index=excluded.order_index, source=excluded.source, deleted=excluded.deleted, created_at=excluded.created_at, updated_at=excluded.updated_at;
INSERT INTO grammar_lesson (id, subject_id, grade, semester, category, title, summary, content_md, examples, common_mistakes, mnemonic, order_index, source, deleted, created_at, updated_at) VALUES (37, 2, 4, NULL, '词法·介词', 'at 表示中午/夜晚', '中午夜晚用 at，太阳月亮都来搭！', '## 这是啥
小朋友们，你们知道吗？在英语里，说“中午”和“夜晚”的时候，要用一个小词——**at**！

就像我们中文说“在中午”“在夜晚”，英语就是 **at noon**、**at night**。

## 怎么用
### 1. 说“在中午”，用 at noon
中午12点左右，太阳在头顶，我们就说 **at noon**。
- 例句：I eat lunch at noon. （我中午吃午饭。）

### 2. 说“在夜晚”，用 at night
天黑了，星星和月亮出来了，我们就说 **at night**。
- 例句：I sleep at night. （我夜晚睡觉。）

### 3. 记住：noon 和 night 前面，只用 at
不说 in noon 或 on night 哦！
- 例句：We have dinner at night. （我们晚上吃晚饭。）

## 小提醒
- at noon = 在中午
- at night = 在夜晚
- 其他时间可能用 in 或 on，但这两个小淘气只跟 at 做朋友！', '[{"en": "I eat lunch at noon.", "zh": "我中午吃午饭。"}, {"en": "She reads a book at night.", "zh": "她夜晚看书。"}, {"en": "We play football at noon.", "zh": "我们中午踢足球。"}, {"en": "The stars come out at night.", "zh": "星星在夜晚出来。"}, {"en": "He goes to bed at night.", "zh": "他夜晚睡觉。"}, {"en": "They have a picnic at noon.", "zh": "他们中午去野餐。"}, {"en": "I brush my teeth at night.", "zh": "我夜晚刷牙。"}]', '["I eat lunch in noon. （错！noon 前用 at）", "She sleeps in night. （错！night 前用 at）", "We play at the noon. （错！noon 前不加 the）", "He reads at night. （对！但注意 night 前不加 the）", "I go to school at noon. （如果中午去学校，对；但如果是上午，要用 in the morning）"]', '中午夜晚 at 来帮，noon 和 night 记心上！', 0, 'manual', 0, '2026-09-18 18:02:51.395322', '2026-09-18 18:03:20.628025') ON CONFLICT(id) DO UPDATE SET subject_id=excluded.subject_id, grade=excluded.grade, semester=excluded.semester, category=excluded.category, title=excluded.title, summary=excluded.summary, content_md=excluded.content_md, examples=excluded.examples, common_mistakes=excluded.common_mistakes, mnemonic=excluded.mnemonic, order_index=excluded.order_index, source=excluded.source, deleted=excluded.deleted, created_at=excluded.created_at, updated_at=excluded.updated_at;
INSERT INTO grammar_lesson (id, subject_id, grade, semester, category, title, summary, content_md, examples, common_mistakes, mnemonic, order_index, source, deleted, created_at, updated_at) VALUES (38, 2, 4, NULL, '词法·介词', '时间介词 in/on/at 的区分', '年月季节用 in，具体某天用 on，几点几分用 at，从小到大记心间！', '## 这是啥
小朋友们，你们有没有发现，说英语的时候，时间前面有时候用 **in**，有时候用 **on**，有时候用 **at**？

别急，它们就像三个小盒子，装的时间不一样大！

- **in** 装的是大盒子：年、月、季节、上午/下午/晚上
- **on** 装的是中盒子：具体某一天、星期几、某天的早上/下午
- **at** 装的是小盒子：几点几分、中午、夜晚

记住：盒子越小，介词越短！

## 怎么用

### 1. 大盒子用 in
**规则**：年、月、季节、上午、下午、晚上，都用 **in**。

**例句**：I get up at 7 o''clock **in the morning**. 我早上7点起床。

### 2. 中盒子用 on
**规则**：具体某一天、星期几、某天的早上/下午/晚上，都用 **on**。

**例句**：We have a party **on Sunday**. 我们星期天有个派对。

### 3. 小盒子用 at
**规则**：几点几分、中午、夜晚，都用 **at**。

**例句**：School starts **at 8 o''clock**. 学校8点开始上课。

### 4. 特殊情况要记牢
**规则**：**at night**（在夜晚）和 **at noon**（在中午）是固定搭配，虽然它们听起来像大盒子，但要用 **at**。

**例句**：I read books **at night**. 我晚上看书。

## 小练习

- 我 **在** 2024年出生 → I was born **in** 2024.
- 我 **在** 星期一上学 → I go to school **on** Monday.
- 我 **在** 7点吃早饭 → I have breakfast **at 7 o''clock**.', '[{"en": "I was born in 2015.", "zh": "我出生在2015年。"}, {"en": "We go swimming in summer.", "zh": "我们夏天去游泳。"}, {"en": "My birthday is on May 1st.", "zh": "我的生日在5月1日。"}, {"en": "We have English class on Monday.", "zh": "我们星期一有英语课。"}, {"en": "I get up at 6:30.", "zh": "我6:30起床。"}, {"en": "She goes to bed at night.", "zh": "她晚上睡觉。"}, {"en": "We eat lunch at noon.", "zh": "我们中午吃午饭。"}, {"en": "It often rains in the morning.", "zh": "早上经常下雨。"}]', '["I go to school in Monday. 应改为 on Monday，因为星期一是一天。", "I get up at the morning. 应改为 in the morning，因为早上是大盒子。", "I was born on 2015. 应改为 in 2015，因为年份是大盒子。", "I sleep in night. 应改为 at night，因为 at night 是固定搭配。", "We have a party in Sunday morning. 应改为 on Sunday morning，因为具体某天的早上用 on。"]', '年月季节用 in，具体某天用 on，几点几分用 at，从小到大记心间！', 0, 'manual', 0, '2026-09-18 18:02:51.562809', '2026-09-18 18:03:24.549372') ON CONFLICT(id) DO UPDATE SET subject_id=excluded.subject_id, grade=excluded.grade, semester=excluded.semester, category=excluded.category, title=excluded.title, summary=excluded.summary, content_md=excluded.content_md, examples=excluded.examples, common_mistakes=excluded.common_mistakes, mnemonic=excluded.mnemonic, order_index=excluded.order_index, source=excluded.source, deleted=excluded.deleted, created_at=excluded.created_at, updated_at=excluded.updated_at;
INSERT INTO grammar_lesson (id, subject_id, grade, semester, category, title, summary, content_md, examples, common_mistakes, mnemonic, order_index, source, deleted, created_at, updated_at) VALUES (39, 2, 5, NULL, '词法·介词', 'before 和 after 表示时间先后', 'Before 在前，After 在后，时间顺序记心头！', '## 这是啥

小朋友们，你们知道吗？

**Before** 就是「在……之前」，**After** 就是「在……之后」。

它们就像时间小警察，告诉我们哪件事先发生，哪件事后发生。

比如：
- 先洗手，**然后**吃饭 → 洗手 **before** 吃饭
- 先吃饭，**然后**睡觉 → 睡觉 **after** 吃饭

## 怎么用

### 1. before 表示「在……之前」

**规则：** before + 事情，表示这件事还没发生，另一件事先发生。

**例句：** I brush my teeth **before** I go to bed.
（我睡觉前刷牙。）

### 2. after 表示「在……之后」

**规则：** after + 事情，表示这件事先发生，另一件事后发生。

**例句：** I play football **after** school.
（我放学后踢足球。）

### 3. before 和 after 后面可以跟名词或句子

**规则：** 后面跟一个名词，或者跟一个完整的小句子。

**例句：**
- **Before** dinner, I do my homework.（晚饭前，我做作业。）
- **After** lunch, we take a nap.（午饭后，我们睡午觉。）

### 4. 用 before 和 after 说一天的生活

**规则：** 把一天的事情按顺序串起来，先说 before，再说 after。

**例句：** **Before** school, I eat breakfast. **After** school, I do my homework.
（上学前，我吃早饭。放学后，我做作业。）

## 小提醒

- before 和 after 后面如果是句子，句子要有主语和动词哦！
- 说「在……之前/之后」时，before 和 after 放在事情的前面。', '[{"en": "I wash my hands before I eat.", "zh": "我吃饭前洗手。"}, {"en": "I go to bed after I brush my teeth.", "zh": "我刷牙后睡觉。"}, {"en": "Before class, we say hello to the teacher.", "zh": "上课前，我们向老师问好。"}, {"en": "After class, we play games.", "zh": "下课后，我们玩游戏。"}, {"en": "She does her homework before dinner.", "zh": "她晚饭前做作业。"}, {"en": "He plays basketball after school.", "zh": "他放学后打篮球。"}, {"en": "Before bed, I read a book.", "zh": "睡觉前，我读一本书。"}, {"en": "After lunch, we take a walk.", "zh": "午饭后，我们散步。"}]', '["I brush my teeth before I go to bed. 不能写成 I brush my teeth before go to bed.（before 后面跟句子时，要有主语 I）", "After school I play football. 不能写成 After school I play football after.（after 不能重复用）", "Before dinner, I do my homework. 不能写成 Before dinner, I do my homework before.（before 不能放在句尾重复）", "I go to bed after I brush my teeth. 不能写成 I go to bed after brush my teeth.（after 后面跟句子时，要有主语 I）", "Before I eat, I wash my hands. 不能写成 Before eat, I wash my hands.（before 后面跟句子时，要有主语 I）"]', 'Before 在前，After 在后，时间顺序不搞错！', 0, 'manual', 0, '2026-09-18 18:02:51.694440', '2026-09-18 18:03:28.633973') ON CONFLICT(id) DO UPDATE SET subject_id=excluded.subject_id, grade=excluded.grade, semester=excluded.semester, category=excluded.category, title=excluded.title, summary=excluded.summary, content_md=excluded.content_md, examples=excluded.examples, common_mistakes=excluded.common_mistakes, mnemonic=excluded.mnemonic, order_index=excluded.order_index, source=excluded.source, deleted=excluded.deleted, created_at=excluded.created_at, updated_at=excluded.updated_at;
INSERT INTO grammar_lesson (id, subject_id, grade, semester, category, title, summary, content_md, examples, common_mistakes, mnemonic, order_index, source, deleted, created_at, updated_at) VALUES (40, 2, 5, NULL, '词法·介词', 'from...to... 表示时间范围', 'from 起点 to 终点，时间范围记心间！', '## 这是啥

小朋友们，from...to... 就像一个小火车，从一站开到另一站。

它告诉我们：**从几点到几点**，或者**从哪天到哪天**。

比如：从 7 点到 8 点，从星期一到星期五。

## 怎么用

### 1. 说时间：从几点到几点

**规则**：from + 开始时间 + to + 结束时间

**例句**：I read books from 7:00 to 8:00.
（我从 7 点读书到 8 点。）

### 2. 说星期：从星期几到星期几

**规则**：from + 星期几 + to + 星期几

**例句**：We go to school from Monday to Friday.
（我们从星期一到星期五上学。）

### 3. 说月份：从几月到几月

**规则**：from + 月份 + to + 月份

**例句**：It is hot from June to August.
（从六月到八月很热。）

### 4. 小提醒

- from 和 to 后面都要加**起点**和**终点**，不能少一个。
- 时间点前面可以加 at，比如 from at 7:00 to at 8:00，但口语里常常省略 at。

## 小练习

试着说：我从星期一到星期三上课。

答案：I have classes from Monday to Wednesday.', '[{"en": "I read books from 7:00 to 8:00.", "zh": "我从 7 点读书到 8 点。"}, {"en": "We go to school from Monday to Friday.", "zh": "我们从星期一到星期五上学。"}, {"en": "It is hot from June to August.", "zh": "从六月到八月很热。"}, {"en": "She plays the piano from 4:00 to 5:00.", "zh": "她从 4 点弹钢琴到 5 点。"}, {"en": "My dad works from Monday to Saturday.", "zh": "我爸爸从星期一到星期六工作。"}, {"en": "We have a holiday from July to August.", "zh": "我们从七月到八月放假。"}, {"en": "The shop is open from 9:00 to 9:00.", "zh": "这家店从 9 点开到 9 点。"}]', '["I go to school from Monday to Friday. 不能写成 I go to school from Monday and Friday.", "from 7:00 to 8:00 不能写成 from 7:00 and 8:00。", "from Monday to Friday 不能写成 from Monday to Friday. 注意 to 不能换成 at。", "from June to August 不能写成 from June and August。", "from...to... 后面要接两个时间，不能只写一个，比如 from Monday 就不完整。"]', 'from 起点，to 终点，时间范围画条线！', 0, 'manual', 0, '2026-09-18 18:02:51.839406', '2026-09-18 18:03:32.148945') ON CONFLICT(id) DO UPDATE SET subject_id=excluded.subject_id, grade=excluded.grade, semester=excluded.semester, category=excluded.category, title=excluded.title, summary=excluded.summary, content_md=excluded.content_md, examples=excluded.examples, common_mistakes=excluded.common_mistakes, mnemonic=excluded.mnemonic, order_index=excluded.order_index, source=excluded.source, deleted=excluded.deleted, created_at=excluded.created_at, updated_at=excluded.updated_at;
INSERT INTO grammar_lesson (id, subject_id, grade, semester, category, title, summary, content_md, examples, common_mistakes, mnemonic, order_index, source, deleted, created_at, updated_at) VALUES (41, 2, 5, NULL, '词法·介词', 'for 表示持续时间', 'for 加一段时间，事情做了多久它来管。', '## 这是啥
小朋友们，for 就像一个小闹钟，专门告诉我们「这件事做了多长时间」。
比如：I read for 20 minutes. 我读了 20 分钟。

## 怎么用
### 要点 1：for + 一段时间
for 后面跟「一段时间」，比如 two days、three hours、a week。
例句：I play football for one hour. 我踢足球一小时。

### 要点 2：放在动作后面
for 短语常常放在句子的后面，说明这个动作持续了多久。
例句：She sleeps for eight hours. 她睡八个小时。

### 要点 3：问多久用 How long
问「多长时间」时，用 How long 开头，回答用 for。
例句：How long do you read? I read for 30 minutes. 你读多久？我读 30 分钟。

### 要点 4：for 后面跟数字 + 时间单位
for 后面要加数字和时间单位，比如 for two days、for five minutes。
例句：We stay in the park for two hours. 我们在公园待两个小时。', '[{"en": "I play football for one hour.", "zh": "我踢足球一小时。"}, {"en": "She sleeps for eight hours.", "zh": "她睡八个小时。"}, {"en": "How long do you read? I read for 30 minutes.", "zh": "你读多久？我读 30 分钟。"}, {"en": "We stay in the park for two hours.", "zh": "我们在公园待两个小时。"}, {"en": "He watches TV for 20 minutes.", "zh": "他看 20 分钟电视。"}, {"en": "They talk for a long time.", "zh": "他们聊了很长时间。"}, {"en": "My mom cooks for 40 minutes.", "zh": "我妈妈做饭 40 分钟。"}]', '["for 后面不能直接加动词，要说 for two hours，不能说 for play。", "How long 问多久，回答要用 for，不能只说 two hours 就结束。", "for 后面要加数字和时间单位，不能说 for hour，要说 for one hour。", "for 表示持续时间时，不能和表示将来的时间混用，比如 I will go for two days 要小心。", "for 后面不能加具体时间点，比如 for 3 o''clock 是错的。"]', 'for 加时间，动作持续记心间；多久就问 How long，回答 for 来帮忙。', 0, 'manual', 0, '2026-09-18 18:02:51.961407', '2026-09-18 18:03:35.611272') ON CONFLICT(id) DO UPDATE SET subject_id=excluded.subject_id, grade=excluded.grade, semester=excluded.semester, category=excluded.category, title=excluded.title, summary=excluded.summary, content_md=excluded.content_md, examples=excluded.examples, common_mistakes=excluded.common_mistakes, mnemonic=excluded.mnemonic, order_index=excluded.order_index, source=excluded.source, deleted=excluded.deleted, created_at=excluded.created_at, updated_at=excluded.updated_at;
INSERT INTO grammar_lesson (id, subject_id, grade, semester, category, title, summary, content_md, examples, common_mistakes, mnemonic, order_index, source, deleted, created_at, updated_at) VALUES (42, 2, 6, NULL, '词法·介词', 'during 表示在……期间', 'during 是“在……期间”，后面跟一段时光，不跟数字和时长。', '## 这是啥
同学们，during 就像一个小导游，带我们走进一段**时间**里。

它说：“在这段时间里，发生了什么事。”

比如：
- during the summer 在夏天期间
- during the class 在上课期间

记住：during 后面跟的是**一段时间**，不是“多久”。

## 怎么用
### 1. during + 一段有名的时间
后面常跟 the summer、the class、the holiday 这样“有名字”的时间。

例句：I read many books during the summer. 我在夏天期间读了很多书。

### 2. during + 节日或活动
节日、比赛、旅行都可以用 during。

例句：We eat mooncakes during the Mid-Autumn Festival. 我们在中秋节期间吃月饼。

### 3. during 和 for 不一样
for 后面跟“多久”，比如 for two hours。
during 后面跟“哪段时间”，比如 during the two hours。

例句：I slept for two hours during the trip. 我在旅行期间睡了两个小时。

### 4. during 后面不加数字
不能说 during three days，要说 during the three days 或 for three days。

例句：It rained during the three days. 在那三天期间下雨了。

## 小提醒
- during 后面通常有 the、my、this 等词。
- during 不单独使用，后面一定要跟时间。
- 说“在……期间”就用 during，简单又地道！', '[{"en": "I read many books during the summer.", "zh": "我在夏天期间读了很多书。"}, {"en": "We eat mooncakes during the Mid-Autumn Festival.", "zh": "我们在中秋节期间吃月饼。"}, {"en": "She fell asleep during the class.", "zh": "她在上课期间睡着了。"}, {"en": "I slept for two hours during the trip.", "zh": "我在旅行期间睡了两个小时。"}, {"en": "It rained during the three days.", "zh": "在那三天期间下雨了。"}, {"en": "He visited many places during the holiday.", "zh": "他在假期期间参观了很多地方。"}, {"en": "Please don''t talk during the movie.", "zh": "看电影期间请不要说话。"}]', '["during 后面不能直接跟数字，比如不能说 during three days，要说 during the three days 或 for three days。", "during 和 for 容易混：for 跟“多久”，during 跟“哪段时间”。", "during 后面不能没有词，不能说 I slept during.，要说 during the night 等。", "during 后面通常要加 the、my、this 等词，比如 during the summer，不是 during summer。", "不要把 during 写成 duringg 或 durring，正确拼写是 d-u-r-i-n-g。"]', 'during 在期间，后面跟段时间；for 跟多久，两个别弄乱！', 0, 'manual', 0, '2026-09-18 18:02:52.110407', '2026-09-18 18:03:39.367884') ON CONFLICT(id) DO UPDATE SET subject_id=excluded.subject_id, grade=excluded.grade, semester=excluded.semester, category=excluded.category, title=excluded.title, summary=excluded.summary, content_md=excluded.content_md, examples=excluded.examples, common_mistakes=excluded.common_mistakes, mnemonic=excluded.mnemonic, order_index=excluded.order_index, source=excluded.source, deleted=excluded.deleted, created_at=excluded.created_at, updated_at=excluded.updated_at;
INSERT INTO grammar_lesson (id, subject_id, grade, semester, category, title, summary, content_md, examples, common_mistakes, mnemonic, order_index, source, deleted, created_at, updated_at) VALUES (43, 2, 6, NULL, '词法·介词', 'until 表示直到……', 'until 就是「一直到」，前面动作不停歇，后面时间一到就结束！', '## 这是啥

小朋友，你有没有等过公交车？

「我一直等到 8 点，公交车才来。」

这里的「一直等到 8 点」，英语就用 **until**！

**until** 的意思是：**直到……为止**。

它就像一个小闹钟，告诉你：

> 前面的动作一直做，做到后面那个时间就停。

## 怎么用

### 要点 1：until 后面跟「时间点」

**规则：** until + 具体时间（几点、某一天、某件事发生的时候）。

**例句：**
I waited until 8 o''clock.
（我一直等到 8 点。）

### 要点 2：前面的动作是「一直做」的

**规则：** until 前面的动作，通常是可以持续的，比如 wait（等）、study（学习）、play（玩）。

**例句：**
She studied until 9 p.m.
（她一直学习到晚上 9 点。）

### 要点 3：not ... until 表示「直到……才……」

**规则：** 如果前面加 not，意思就变成「直到……才……」。

**例句：**
He didn''t sleep until 10 p.m.
（他直到晚上 10 点才睡觉。）

### 要点 4：until 和 till 一样

**规则：** till 是 until 的口语小名，意思完全一样，写作文时用 until 更正式。

**例句：**
Let''s play till 5 o''clock.
（我们玩到 5 点吧。）

## 小提醒

- until 后面**不跟**「一段时间」，比如 two hours。
- 想说「等了两小时」，要用 for two hours。
- until 后面跟的是「终点时间」，不是「持续多久」。', '[{"en": "I waited until 8 o''clock.", "zh": "我一直等到 8 点。"}, {"en": "She studied until 9 p.m.", "zh": "她一直学习到晚上 9 点。"}, {"en": "He didn''t sleep until 10 p.m.", "zh": "他直到晚上 10 点才睡觉。"}, {"en": "Let''s play till 5 o''clock.", "zh": "我们玩到 5 点吧。"}, {"en": "We walked until we got home.", "zh": "我们一直走到家。"}, {"en": "Don''t watch TV until you finish your homework.", "zh": "直到写完作业才能看电视。"}, {"en": "The shop is open until 9 p.m.", "zh": "这家店一直开到晚上 9 点。"}]', '["I waited until two hours. 应改成 I waited for two hours.（until 后面跟时间点，不跟一段时间）", "He didn''t sleep until 10 p.m. 不能写成 He didn''t sleep till 10 p.m. 就错，till 也可以，但作文里最好用 until。", "We played until 5 o''clock. 不能写成 We played until five hours.", "She studied until 9 p.m. 不能写成 She studied until at 9 p.m.（until 后面直接跟时间，不加 at）", "I will wait until you come back. 不能写成 I will wait until you will come back.（until 后面用一般现在时表示将来）"]', 'Until 直到终点站，前面动作不停转；not until 才出现，时间一到就靠岸！', 0, 'manual', 0, '2026-09-18 18:02:52.264406', '2026-09-18 18:03:43.875222') ON CONFLICT(id) DO UPDATE SET subject_id=excluded.subject_id, grade=excluded.grade, semester=excluded.semester, category=excluded.category, title=excluded.title, summary=excluded.summary, content_md=excluded.content_md, examples=excluded.examples, common_mistakes=excluded.common_mistakes, mnemonic=excluded.mnemonic, order_index=excluded.order_index, source=excluded.source, deleted=excluded.deleted, created_at=excluded.created_at, updated_at=excluded.updated_at;
INSERT INTO grammar_lesson (id, subject_id, grade, semester, category, title, summary, content_md, examples, common_mistakes, mnemonic, order_index, source, deleted, created_at, updated_at) VALUES (44, 2, 6, NULL, '词法·介词', 'by 表示到……之前', 'by 加时间，表示‘到……之前’做完事，就像赛跑要在铃响前冲过线！', '## 这是啥
by 就像一个小闹钟，它说：“到几点之前，你要做完这件事哦！”
比如：**by 7 o''clock** 就是“在7点之前”。

## 怎么用
### 1. by + 时间点，表示“不晚于这个时间”
- 规则：by 后面跟一个具体时间，比如 by 6:00, by Monday。
- 例句：I do my homework by 7 o''clock.（我在7点之前做完作业。）

### 2. by + 一天/日期，表示“在那天之前”
- 规则：by 后面可以跟星期、日期，比如 by Friday, by May 1st。
- 例句：We go to the park by Sunday.（我们在星期天之前去公园。）

### 3. by 和 before 有点像，但 by 强调“最晚到那个时间”
- 规则：by 说的是“最晚不晚于”，before 只是“在……之前”。
- 例句：Please come back by 5:00.（请最晚5点前回来。）

### 4. by 后面跟时间，句子常用一般现在时或将来时
- 规则：说习惯用一般现在时，说将来用 will。
- 例句：I will finish it by tomorrow.（我会在明天之前完成它。）

## 小提醒
- by 后面不能加 for 或 in，直接加时间。
- by 和 until 不同：by 是“到……之前做完”，until 是“一直做到……”。', '[{"en": "I get up by 6:30 every day.", "zh": "我每天6:30之前起床。"}, {"en": "She will come back by Friday.", "zh": "她会在星期五之前回来。"}, {"en": "We must finish the game by 4 o''clock.", "zh": "我们必须在4点之前完成游戏。"}, {"en": "Please send me the picture by Monday.", "zh": "请在星期一之前把照片发给我。"}, {"en": "He will be home by dinner time.", "zh": "他会在晚饭前到家。"}, {"en": "Can you do it by tomorrow?", "zh": "你能在明天之前做完吗？"}, {"en": "I read this book by last Sunday.", "zh": "我在上周日之前读完了这本书。"}]', '["I will finish it by tomorrow morning. 不能写成 I will finish it in tomorrow morning.", "by 后面不能加 for，比如 by for 6 o''clock 是错的。", "by 和 until 不要混：I will wait until 6 o''clock.（我一直等到6点）不是 by。", "by Friday 表示“最晚星期五”，不是“在星期五之后”。", "by 后面直接跟时间，不要加 at，比如 by at 5:00 是错的。"]', 'by 加时间，到点前；最晚不晚，记心间！', 0, 'manual', 0, '2026-09-18 18:02:52.421406', '2026-09-18 18:03:48.155734') ON CONFLICT(id) DO UPDATE SET subject_id=excluded.subject_id, grade=excluded.grade, semester=excluded.semester, category=excluded.category, title=excluded.title, summary=excluded.summary, content_md=excluded.content_md, examples=excluded.examples, common_mistakes=excluded.common_mistakes, mnemonic=excluded.mnemonic, order_index=excluded.order_index, source=excluded.source, deleted=excluded.deleted, created_at=excluded.created_at, updated_at=excluded.updated_at;
